/** All translations for zizhitongjian ch.047 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第047卷", literal: "Zizhi Tongjian, Volume 47.", idiomatic: "Zizhi Tongjian, Volume 47." },
  { zh: "【漢紀三十九】起旃蒙作噩，盡重光單閼，凡七年。", literal: "【Han Records 39】 From Zhanmeng Zuoe through Chongguang Dan'e—in all, seven years.", idiomatic: "【Han Records 39】 From the first year of the Zhanmeng cycle through the last year of the Chongguang cycle—seven years in all." },
  { zh: "春，正月，乙酉，詔曰：「令云：『民有產子者，復勿算三歲。", literal: "In spring, the first month, on the day yiyou, an edict said: \"The ordinance states: 'When the people bear a child, remit and do not count levies for three years.'\"", idiomatic: "In spring, in the first month, on yiyou day, an edict ran, \"The ordinance says, 'When a household has a child, remit levies and exempt them from corvée registration for three years.'\"" },
  { zh: "』今諸懷妊者，賜胎養谷人三斛，復其夫勿算一歲。", literal: "\"'Now for all who are pregnant, grant three hu of grain for fetal nourishment per person, and remit the husband from counting levies for one year.\"", idiomatic: "\"'Now every woman with child shall receive three hu of grain for fetal nourishment, and her husband shall be remitted from corvée registration for one year.\"" },
  { zh: "著以為令！", literal: "\"Record this and make it an ordinance!\"", idiomatic: "\"Let this be recorded as law!\"" },
  { zh: "」又詔三公曰：「夫欲吏矯飾外貌，似是而非，朕甚饜之，甚苦之！", literal: "\" Moreover an edict to the Three Excellencies said: \"Those who wish that officials adorn and polish their outward appearance, seeming so yet not so—I am very surfeited with this, very pained by it!\"", idiomatic: "\" The emperor also addressed the Three Excellencies, \"When officials dress up their outward show, seeming right yet wrong—I am sick of it, sick at heart!\"" },
  { zh: "安靜之吏，悃愊無華，日計不足，月計有餘。", literal: "\"Quiet and still officials, sincere and plain without flourish—day's reckoning falls short, month's reckoning has surplus.\"", idiomatic: "\"The quiet official, sincere and without show, may fall short day by day yet surpass the month.\"" },
  { zh: "如襄城令劉方，吏民同聲謂之不煩，雖未有它異，斯亦殆近之矣！", literal: "\"Like Magistrate Liu Fang of Xiangcheng—the clerks and people with one voice call him untroublesome; though there is not yet other strangeness, this also is nearly close to it!\"", idiomatic: "\"Magistrate Liu Fang of Xiangcheng—officials and people alike say he never wearies them. Though he has done nothing extraordinary, he comes very near it.\"" },
  { zh: "夫以苛為察，以刻為明，以輕為德，以重為威，四者或興，則下有怨心。", literal: "\"To take harshness as scrutiny, severity as clarity, lightness as virtue, heaviness as awe—if any of the four arise, then below there is a heart of resentment.\"", idiomatic: "\"To take harshness for scrutiny, severity for clarity, lenience for virtue, and severity for awe—if any of these four arise, the people below will resent.\"" },
  { zh: "吾詔書數下，冠蓋接道，而吏不加治，民或失職，其咎安在？", literal: "\"Our edicts have gone down repeatedly, caps and canopies fill the road, yet officials do not add governance and the people sometimes lose their posts—where lies the fault?\"", idiomatic: "\"My edicts have gone out again and again until the roads teem with envoys, yet officials do not govern better and the people still lose their livelihood—where does the blame lie?\"" },
  { zh: "勉思舊令，稱朕意焉！", literal: "\"Strive to ponder the old ordinances and match Our intent!\"", idiomatic: "\"Strive to recall the old ordinances and answer my intent!\"" },
  { zh: "北匈奴大人車利涿兵等亡來入塞，凡七十三輩。", literal: "The Northern Xiongnu great men Chelizhuo Bing and others fled and came within the passes—in all, seventy-three groups.", idiomatic: "Great men of the Northern Xiongnu, Chelizhuo Bing and others, fled and entered the passes—seventy-three groups in all." },
  { zh: "時北虜衰耗，黨眾離畔，南部攻其前，丁零寇其後，鮮卑擊其左，西域侵其右，不復自立，乃遠引而去。", literal: "At this time the northern foe was in decline and waste; clans and masses split away. The Southern [Xiongnu] attacked their front, the Dingling raided their rear, the Xianbei struck their left, the Western Regions encroached on their right—they could no longer stand alone and so drew far off and left.", idiomatic: "The northern foe was failing. Their clans split apart. The Southern Xiongnu struck from the front, the Dingling raided the rear, the Xianbei hit the left, the Western Regions pressed the right. They could no longer hold together and withdrew far away." },
  { zh: "南單于長死，單于汗之子宣立，為伊屠於閭鞮單于。", literal: "The Southern Chanyu Chang died. The chanyu's son Xuan by Han was established as Chanyu Yitu Yulüdi.", idiomatic: "Southern Chanyu Chang died. Xuan, son of Chanyu Han, was enthroned as Yitu Yulüdi Chanyu." },
  { zh: "《太初歷》施行百餘年，歷稍後天。", literal: "The Taichu Calendar had been in use more than a hundred years; the calendar gradually lagged Heaven.", idiomatic: "The Taichu Calendar had been in use for more than a hundred years, and it gradually fell behind the heavens." },
  { zh: "上命治歷編訢、本梵等綜校其狀，作《四分歷》；", literal: "The emperor ordered the calendar officers Bian Xin, Ben Fan, and others comprehensively to collate its condition and compose the Quarter-Remainder Calendar;", idiomatic: "The emperor ordered calendar officers Bian Xin, Ben Fan, and others to collate its drift and compose the Quarter-Remainder Calendar;" },
  { zh: "二月，甲寅，始施行之。", literal: "in the second month, on the day jiayin, it was first put into practice.", idiomatic: "in the second month, on jiayin day, it was first put into practice." },
  { zh: "帝之為太子也，受《尚書》於東郡太守汝南張酺。", literal: "When the emperor was heir apparent, he received the Documents from Zhang Pei of Runan, Administrator of Dongjun.", idiomatic: "When the emperor was heir apparent, he studied the Documents under Zhang Pei of Runan, Administrator of Dongjun." },
  { zh: "丙辰，帝東巡，幸東郡，引酺及門生並郡縣掾史並會庭中。", literal: "On the day bingchen, the emperor toured east, visited Dongjun, and summoned Pei, his students, and the commandery and district clerks together to meet in the courtyard.", idiomatic: "On bingchen day the emperor toured east and visited Dongjun. He summoned Pei, his students, and the commandery and district clerks to meet in the courtyard." },
  { zh: "帝先備弟子之儀，使酺講《尚書》一篇，然後修君臣之禮；", literal: "The emperor first prepared the rites of a disciple, had Pei lecture one chapter of the Documents, and only then observed the rites of ruler and minister;", idiomatic: "The emperor first took the rites of a disciple and had Pei lecture one chapter of the Documents, then observed the rites between ruler and minister;" },
  { zh: "賞賜殊特，莫不沾洽。", literal: "rewards and gifts were extraordinary; none went without full share.", idiomatic: "rewards were extraordinary, and none went without his share." },
  { zh: "行過任城，幸鄭均捨，賜尚書祿以終其身，時人號為「白衣尚書」。", literal: "Passing Ren, he visited Zheng Jun's dwelling, granted him the salary of a Master of Writing for life, and men of the time called him \"Master of Writing in White.\"", idiomatic: "Passing Ren, he visited Zheng Jun's home and granted him a Master of Writing's salary for life. Men of the time called him \"the Master of Writing in white robes.\"" },
  { zh: "乙丑，帝耕於定陶。", literal: "On the day yichou, the emperor plowed at Dingtao.", idiomatic: "On yichou day the emperor plowed the sacred field at Dingtao." },
  { zh: "辛未，幸泰山，柴告岱宗；", literal: "On the day xinwei, he visited Mount Tai and offered firewood to announce to the Lord of Dai;", idiomatic: "On xinwei day he visited Mount Tai and offered firewood to announce to the Lord of Dai;" },
  { zh: "進幸奉高。", literal: "he advanced to visit Fenggao.", idiomatic: "then advanced to Fenggao." },
  { zh: "壬申，宗祀五帝於汶上明堂；", literal: "On the day renshen, he performed ancestral sacrifice to the Five Emperors at the Bright Hall above the Wen;", idiomatic: "On renshen day he sacrificed to the Five Emperors at the Bright Hall on the Wen;" },
  { zh: "丙子，赦天下。", literal: "On the day bingzi, he pardoned the realm.", idiomatic: "On bingzi day he pardoned the realm." },
  { zh: "戊寅，進幸濟南。", literal: "On the day wuyin, he advanced to visit Jinan.", idiomatic: "On wuyin day he advanced to Jinan." },
  { zh: "三月，己丑，幸魯，庚寅，祠孔子於闕裡，及七十二弟子，作六代之樂，大會孔氏男子二十以上者六十二人。", literal: "In the third month, on the day jichou, he visited Lu; on the day gengyin he sacrificed to Confucius at Que Li and to the seventy-two disciples, performed the music of the six dynasties, and greatly assembled sixty-two men of the Kong clan aged twenty and above.", idiomatic: "In the third month, on jichou day he visited Lu. On gengyin day he sacrificed to Confucius at Que Li and to the seventy-two disciples, performed the music of the six dynasties, and gathered sixty-two Kong clansmen aged twenty and above." },
  { zh: "帝謂孔僖曰：「今日之會，寧於卿宗有光榮乎？", literal: "The emperor said to Kong Xi: \"Today's gathering—does it not bring glory to your clan?\"", idiomatic: "The emperor said to Kong Xi, \"Does today's gathering bring glory to your clan?\"" },
  { zh: "」對曰：「臣聞明王聖主，莫不尊師貴道。", literal: "\" He replied: \"Your servant has heard that enlightened kings and sage rulers all honor their teachers and prize the Way.\"", idiomatic: "\" He answered, \"I have heard that enlightened kings and sage rulers all honor their teachers and prize the Way.\"" },
  { zh: "今陛下親屈萬乘，辱臨敝裡，此乃崇禮先師，增輝聖德；", literal: "\"Now Your Majesty in person bends the ten-thousand chariots and deigns to visit this humble hamlet—this is to exalt rites toward the former teacher and add luster to sage virtue;\"", idiomatic: "\"Now Your Majesty in person bends the imperial carriage and stoops to this humble hamlet. That exalts rites toward the former teacher and adds luster to sage virtue;\"" },
  { zh: "至於光榮，非所敢承。", literal: "\"as for glory, it is not what I dare receive.\"", idiomatic: "\"as for glory, I dare not claim it.\"" },
  { zh: "」帝大笑曰：「非聖者子孫焉有斯言乎！", literal: "\" The emperor laughed greatly and said: \"Were one not a sage's descendant, how could there be such words!\"", idiomatic: "\" The emperor laughed and said, \"Only a sage's descendant could speak such words!\"" },
  { zh: "」拜僖郎中。", literal: "\" He appointed Xi Gentleman of the Palace.", idiomatic: "\" He appointed Xi Gentleman of the Palace." },
  { zh: "壬辰，帝幸東平，追念獻王，謂其諸子曰：「思其人，至其鄉；", literal: "On the day renchen, the emperor visited Dongping, recalled Prince Xian, and said to his sons: \"When one thinks of a man, one comes to his village;\"", idiomatic: "On renchen day the emperor visited Dongping, recalled Prince Xian, and said to his sons, \"When you think of a man, you come to his village;\"" },
  { zh: "其處在，其人亡。", literal: "\"the place remains, the man is gone.\"", idiomatic: "\"the place remains, but the man is gone.\"" },
  { zh: "」因泣下沾襟。", literal: "\" He thereupon wept until his breast was soaked.", idiomatic: "\" He wept until his robe was soaked." },
  { zh: "遂幸獻王陵，祠以太牢，親拜祠坐，哭泣盡哀。", literal: "He then visited Prince Xian's tomb, sacrificed with the great offering, personally bowed at the sacrificial seat, and wept with full grief.", idiomatic: "He then visited Prince Xian's tomb, sacrificed with the great offering, bowed in person at the sacrificial seat, and wept his fill." },
  { zh: "獻王之歸國也，驃騎府吏丁牧、周栩以王愛賢下士，不忍去之，遂為王家大夫數十年，事祖及孫。", literal: "When Prince Xian returned to his state, the Rapid Cavalry office clerks Ding Mu and Zhou Xu, because the prince loved the worthy and lowered himself to scholars, could not bear to leave and thereupon became the royal house's grandees for several decades, serving grandfather and grandson.", idiomatic: "When Prince Xian returned to his state, Rapid Cavalry clerks Ding Mu and Zhou Xu, because the prince loved worthies and honored scholars, could not bear to leave. They became grandees of the royal house for decades, serving grandfather and grandson." },
  { zh: "帝聞之，皆引見，既愍其淹滯，且欲揚獻王德美，即皆擢為議郎。", literal: "The emperor heard of this and summoned them all. Both pitying their long stagnation and wishing to display Prince Xian's virtue and beauty, he at once promoted them all to Gentlemen Consultant.", idiomatic: "The emperor heard of them and summoned them all. Pitying their long stagnation and wishing to display Prince Xian's virtue, he at once promoted them all to Gentlemen Consultant." },
  { zh: "乙未，幸東阿，北登太行山，至天井關。", literal: "On the day yiwei, he visited Dong'e, climbed the Taihang Mountains to the north, and reached Tianjing Pass.", idiomatic: "On yiwei day he visited Dong'e, climbed the Taihang to the north, and reached Tianjing Pass." },
  { zh: "夏，四月，乙卯，還宮。", literal: "In summer, the fourth month, on the day yimao, he returned to the palace.", idiomatic: "In summer, in the fourth month, on yimao day he returned to the palace." },
  { zh: "庚申，假於祖檷。", literal: "On the day gengshen, he stayed at the ancestral shrine.", idiomatic: "On gengshen day he stayed at the ancestral shrine." },
  { zh: "五月，徙江陵王恭為六安王。", literal: "In the fifth month, Prince Gong of Jiangling was moved to be Prince of Lu'an.", idiomatic: "In the fifth month Prince Gong of Jiangling was moved to be Prince of Lu'an." },
  { zh: "秋，七月，庚子，詔曰：「《春秋》重三正，慎三微。", literal: "In autumn, the seventh month, on the day gengzi, an edict said: \"The Spring and Autumn esteems the three beginnings and is careful of the three subtle days.\"", idiomatic: "In autumn, in the seventh month, on gengzi day, an edict ran, \"The Spring and Autumn esteems the three beginnings and is careful of the three subtle days.\"" },
  { zh: "其定律無以十一月、十二月報囚，止用冬初十月而已。", literal: "\"In setting law, do not use the eleventh and twelfth months to report prisoners—use only the first month of winter, the tenth month.\"", idiomatic: "\"In setting law, do not try prisoners in the eleventh and twelfth months. Use only the tenth month at the start of winter.\"" },
  { zh: "冬，南單于遣兵與北虜溫禺犢王戰於涿邪山，斬獲而還。", literal: "In winter, the Southern Chanyu sent troops to fight the northern foe's King Wen'yu Du at Zhuoye Mountain, beheaded and captured, and returned.", idiomatic: "In winter the Southern Chanyu sent troops to fight the northern foe's King Wen'yu Du at Zhuoye Mountain, took heads and captives, and returned." },
  { zh: "武威太守孟雲上言：「北虜以前既和親，而南部復往抄掠，北單于謂漢欺之，謀欲犯塞，謂宜還南所掠生口以慰安其意。", literal: "Administrator of Wuwei Meng Yun memorialized: \"The northern foe had earlier made peace through marriage alliance, yet the Southern [Xiongnu] again went to raid and plunder. The Northern Chanyu holds that Han deceived him and plots to invade the passes. I hold that one ought to return the living captives the south seized to comfort and settle his heart.\"", idiomatic: "Administrator of Wuwei Meng Yun memorialized, \"The northern foe had already made peace by marriage alliance, yet the south again raided and plundered. The Northern Chanyu believes Han deceived him and plots to invade the passes. I hold that the living captives the south seized should be returned to comfort him.\"" },
  { zh: "」詔百官議於朝堂。", literal: "\" An edict ordered the hundred officials to deliberate in the court hall.", idiomatic: "\" An edict ordered the hundred officials to deliberate in the court hall." },
  { zh: "太尉鄭弘、司空第五倫以為不可許，司徒桓虞及太僕袁安以為當與之。", literal: "Grand Commandant Zheng Hong and Minister of Works Fifth Lun held that it could not be permitted; Minister of Education Huan Yu and Grand Master of Splendid Horses Yuan An held that they ought to be given.", idiomatic: "Grand Commandant Zheng Hong and Minister of Works Fifth Lun held it could not be permitted. Minister of Education Huan Yu and Grand Master of Splendid Horses Yuan An held they ought to be returned." },
  { zh: "弘因大言激厲虞曰：「諸言當還生口者，皆為不忠！", literal: "Hong thereupon spoke loudly and sharply to stir Huan Yu: \"All who say the living captives ought to be returned are disloyal!\"", idiomatic: "Hong then spoke loudly and sharply to Huan Yu, \"All who say the captives ought to be returned are disloyal!\"" },
  { zh: "」虞延叱之，倫及大鴻臚韋彪各作色變容。", literal: "\" Yu shouted him down in the hall; Lun and the Grand Herald Wei Biao each changed color and altered their faces.", idiomatic: "\" Yu shouted him down in the hall. Lun and Grand Herald Wei Biao each changed color." },
  { zh: "司隸校尉舉奏弘等，弘等皆上印綬謝。", literal: "The Director of Retainers memorialized against Hong and the others; Hong and the others all submitted seal and cord in apology.", idiomatic: "The Director of Retainers memorialized against Hong and the others. They all submitted seal and cord in apology." },
  { zh: "詔報曰：「久議沉滯，各有所志，蓋事以議從，策由眾定，誾誾衎衎，得禮之容，寢嘿抑心，更非朝廷之福。", literal: "The edict in reply said: \"Long deliberation sank and stalled; each had his own intent. Generally affairs follow where deliberation goes and plans are settled by the multitude—harmonious and easy, gaining the bearing of rites. To lie silent and suppress the heart is instead not the court's blessing.\"", idiomatic: "The edict in reply said, \"Deliberation dragged on and each had his own intent. Affairs follow counsel and plans are settled by the multitude—harmonious debate is the bearing of rites. To lie silent and suppress the heart is no blessing to the court.\"" },
  { zh: "君何尤而深謝！", literal: "\"Why do you take fault and apologize so deeply!\"", idiomatic: "\"Why take fault and apologize so deeply!\"" },
  { zh: "其各冠覆！", literal: "\"Each of you put on cap and return!\"", idiomatic: "\"Each of you put on your caps again!\"" },
  { zh: "」帝乃下詔曰：「江海所以能長百川者，以其下之也。", literal: "\" The emperor then issued an edict: \"Rivers and seas can long nourish the hundred streams because they lie below them.\"", idiomatic: "\" The emperor then issued an edict, \"Rivers and seas can long nourish a hundred streams because they lie below them.\"" },
  { zh: "少加屈下，尚何足病！", literal: "\"A little added bending low—how could it suffice for illness!\"", idiomatic: "\"A little added humility—what harm is there!\"" },
  { zh: "況今與匈奴君臣分定，辭順約明，貢獻累至，豈宜違信，自受其曲！", literal: "\"Moreover, now with the Xiongnu ruler and minister's division settled, words compliant and covenant clear, tribute arriving again and again—how should one violate faith and oneself accept the crooked!\"", idiomatic: "\"Moreover, with the Xiongnu ruler and minister's roles settled, words compliant and the covenant clear, tribute arriving again and again—how should we violate faith and accept the crooked ourselves!\"" },
  { zh: "其敕度遼及領中郎將龐奮，倍雇南部所得生口以還北虜；", literal: "\"Order the Crossing-Liao [general] and the Colonel of the Palace Guard Pang Fen to double the hire-price for living captives the south obtained and return them to the northern foe;\"", idiomatic: "\"Order the Crossing-Liao commander and Colonel of the Palace Guard Pang Fen to pay double hire for the living captives the south obtained and return them to the northern foe;\"" },
  { zh: "其南部斬首獲生，計功受賞，如常科。", literal: "\"as for the south's beheading heads and capturing the living, reckon merit and receive reward according to the usual statute.\"", idiomatic: "\"as for the south's beheadings and captures, reckon merit and reward by the usual statute.\"" },
  { zh: "春，正月，丙申，帝北巡，辛丑，耕於；", literal: "In spring, the first month, on the day bingshen, the emperor toured north; on the day xinchou, he plowed at —;", idiomatic: "In spring, in the first month, on bingshen day the emperor toured north; on xinchou day he plowed at —;" },
  { zh: "二月，乙丑，敕侍御史、司空曰：「方春所過，無得有所伐殺，車可以引避，引避之：騑馬可輟解，輟解之。", literal: "In the second month, on the day yichou, he charged the Attendant Censor and Minister of Works: \"In spring, where we pass, none may cut or kill. Where a carriage can turn aside, turn aside; where outrider horses can be unhitched, unhitch them.\"", idiomatic: "In the second month, on yichou day, he charged the Attendant Censor and Minister of Works, \"In spring, along our route none may cut or kill. Where a carriage can turn aside, let it turn aside. Where outrider horses can be unhitched, unhitch them.\"" },
  { zh: "」戊辰，進幸中山，出長城；", literal: "\" On the day wuchen, he advanced to visit Zhongshan and went out through the Long Wall;", idiomatic: "\" On wuchen day he advanced to Zhongshan and went out through the Long Wall;" },
  { zh: "癸酉，還，幸元氏；", literal: "on the day guiyou, he returned and visited Yuanshi;", idiomatic: "on guiyou day he returned and visited Yuanshi;" },
  { zh: "三月，己卯，進幸趙；", literal: "in the third month, on the day jimao, he advanced to visit Zhao;", idiomatic: "in the third month, on jimao day he advanced to Zhao;" },
  { zh: "辛卯，還宮。", literal: "on the day xinmao, he returned to the palace.", idiomatic: "on xinmao day he returned to the palace." },
  { zh: "太尉鄭弘數陳侍中竇憲權勢太盛，言甚苦切，憲疾之。", literal: "Grand Commandant Zheng Hong repeatedly presented that Attendant Dou Xian's power and influence were too great; his words were very bitter and cutting. Xian resented him.", idiomatic: "Grand Commandant Zheng Hong repeatedly warned that Attendant Dou Xian's power was too great, speaking with bitter force. Xian resented him." },
  { zh: "會弘奏憲黨尚書張林、雒陽令楊光在官貪殘。", literal: "It happened that Hong memorialized that Xian's faction—Master of Writing Zhang Lin and Magistrate of Luoyang Yang Guang—were greedy and cruel in office.", idiomatic: "It happened that Hong memorialized that Xian's faction—Master of Writing Zhang Lin and Magistrate of Luoyang Yang Guang—were greedy and cruel in office." },
  { zh: "書奏，吏與光故舊，因以告之，光報憲。", literal: "When the memorial was submitted, a clerk was an old acquaintance of Guang and so informed him; Guang reported to Xian.", idiomatic: "When the memorial was submitted, a clerk who was Guang's old acquaintance informed him. Guang reported to Xian." },
  { zh: "憲奏弘大臣，漏洩密事，帝詰讓弘。", literal: "Xian memorialized that Hong, a great minister, had leaked secret affairs. The emperor reproached Hong.", idiomatic: "Xian memorialized that Hong, a great minister, had leaked secret affairs. The emperor reproached Hong." },
  { zh: "夏，四月，丙寅，收弘印緩。", literal: "In summer, the fourth month, on the day bingyin, Hong's seal and cord were taken.", idiomatic: "In summer, in the fourth month, on bingyin day Hong's seal and cord were taken." },
  { zh: "弘自詣延尉，詔敕出之，因乞骸骨歸，未許。", literal: "Hong himself went to the Commandant of Justice. An edict ordered him released, and he thereupon begged to return home on worn bones—not yet permitted.", idiomatic: "Hong went himself to the Commandant of Justice. An edict ordered him released, and he begged to retire on worn bones—not yet permitted." },
  { zh: "病篤，上書陳謝曰：「竇憲奸惡，貫天達地，海內疑惑，賢愚疾惡，謂『憲何術以迷主上！", literal: "Gravely ill, he submitted a memorial of apology: \"Dou Xian is treacherous and wicked, piercing Heaven and reaching Earth. Within the seas there is doubt; worthy and foolish alike loathe him, saying, 'By what art does Xian bewitch the sovereign!'", idiomatic: "Gravely ill, he submitted a memorial of apology, \"Dou Xian is treacherous and wicked, piercing Heaven and reaching Earth. The realm is in doubt. Worthy and foolish alike loathe him, saying, 'By what art does Xian bewitch the sovereign!'" },
  { zh: "近日王氏之禍，昺然可見。", literal: "\"The Wang clan's calamity of recent days is bright and can be seen.\"", idiomatic: "\"The Wang clan's calamity of recent days stands plain to see.\"" },
  { zh: "』陛下處天子之尊，保萬世之祚，而信讒佞之臣，不計存亡之機；", literal: "\"'Your Majesty occupies the Son of Heaven's eminence and preserves the fortune of ten thousand generations, yet trusts slanderous and fawning ministers and does not reckon the hinge of survival and ruin;\"", idiomatic: "\"'Your Majesty holds the Son of Heaven's eminence and preserves the fortune of ten thousand generations, yet trusts slanderous and fawning ministers and does not reckon the hinge of survival and ruin;\"" },
  { zh: "臣雖命在晷刻，死不忘忠，願陛下誅四凶之罪，以厭人鬼憤結之望！", literal: "\"your servant though life lasts but a sundial's moment, in death will not forget loyalty. I wish Your Majesty would punish the guilt of the Four Evils to satisfy the hope of men and ghosts knotted in rage!\"", idiomatic: "\"though my life lasts but a sundial's moment, in death I shall not forget loyalty. I beg Your Majesty to punish the guilt of the Four Evils and satisfy the knotted rage of men and ghosts!\"" },
  { zh: "」帝省章，遣醫視弘病，比至，已薨。", literal: "\" The emperor read the memorial and sent a physician to attend Hong's illness; by the time he arrived, Hong had already died.", idiomatic: "\" The emperor read the memorial and sent a physician to attend Hong. By the time he arrived, Hong was already dead." },
  { zh: "以大司農宋由為太尉。", literal: "Grand Minister of Agriculture Song You was made Grand Commandant.", idiomatic: "Grand Minister of Agriculture Song You was made Grand Commandant." },
  { zh: "司空第五倫以老病乞身，五月，丙子，賜策罷，以二千石俸終其身。", literal: "Minister of Works Fifth Lun, on account of age and illness, begged to leave office. In the fifth month, on the day bingzi, he was granted a writ of dismissal and given two-thousand-dan salary for life.", idiomatic: "Minister of Works Fifth Lun, aged and ill, begged to leave office. In the fifth month, on bingzi day, he was granted dismissal and two-thousand-dan salary for life." },
  { zh: "倫奉公盡節，言事無所依違。", literal: "Lun served the public to the limit of integrity; in speaking on affairs he never leaned or bent away.", idiomatic: "Lun served the public to the limit of integrity and never bent his words on affairs." },
  { zh: "性質愨，少文采，在位以貞白稱。", literal: "His nature was plain and honest, with little literary color; in office he was known as chaste and white.", idiomatic: "His nature was plain and honest, with little literary color. In office he was known for chaste integrity." },
  { zh: "或問倫曰：「公有私乎？", literal: "Someone asked Lun: \"Does the minister have private ends?\"", idiomatic: "Someone asked Lun, \"Do you have private ends?\"" },
  { zh: "」對曰：「昔人有與吾千里馬者，吾雖不受，每三公有所選舉，心不能忘，而亦終不用也。", literal: "\" He replied: \"Once a man gave me a thousand-li horse. Though I did not accept it, whenever the Three Excellencies had a selection and promotion, I could not forget it in my heart—yet in the end I never used him.\"", idiomatic: "\" He answered, \"Once a man offered me a thousand-li horse. Though I did not accept it, whenever the Three Excellencies made a selection I could not forget him in my heart—yet in the end I never used him.\"" },
  { zh: "若是者，豈可謂無私乎！", literal: "\"If it is so, how can one say there is no private end!\"", idiomatic: "\"If that is so, how can one say there is no private end!\"" },
  { zh: "以太僕袁安為司空。", literal: "Grand Master of Splendid Horses Yuan An was made Minister of Works.", idiomatic: "Grand Master of Splendid Horses Yuan An was made Minister of Works." },
  { zh: "秋，八月，乙丑，帝幸安邑，觀鹽池。", literal: "In autumn, the eighth month, on the day yichou, the emperor visited Anyi and viewed the salt ponds.", idiomatic: "In autumn, in the eighth month, on yichou day the emperor visited Anyi and viewed the salt ponds." },
  { zh: "九月，還宮。", literal: "In the ninth month, he returned to the palace.", idiomatic: "In the ninth month he returned to the palace." },
  { zh: "燒當羌迷吾復與弟號吾及諸種反。", literal: "Mi Wu of the Shaodang Qiang again rebelled with his younger brother Hao Wu and the various tribes.", idiomatic: "Mi Wu of the Shaodang Qiang rebelled again with his younger brother Hao Wu and the various tribes." },
  { zh: "號吾先輕入，寇隴西界，督烽掾李章追之，生得號吾，將詣郡。", literal: "Hao Wu first entered lightly, raided the borders of Longxi; Beacon Supervisor Clerk Li Zhang pursued him, captured Hao Wu alive, and was about to take him to the commandery.", idiomatic: "Hao Wu first raided lightly into Longxi borders. Beacon Supervisor Clerk Li Zhang pursued him, took Hao Wu alive, and was taking him to the commandery." },
  { zh: "號吾曰：「獨殺我，無損於羌；", literal: "Hao Wu said: \"To kill me alone does no harm to the Qiang;\"", idiomatic: "Hao Wu said, \"To kill me alone does the Qiang no harm;\"" },
  { zh: "誠得生歸，必悉罷兵，不復犯塞。", literal: "\"if I truly may return alive, I shall surely wholly dismiss the troops and not again invade the passes.\"", idiomatic: "\"if I truly return alive, I shall surely dismiss all troops and not again invade the passes.\"" },
  { zh: "」隴西太守張紆放遣之，羌即為解散，各歸故地。", literal: "\" Administrator of Longxi Zhang Yu released and sent him off; the Qiang at once dispersed and each returned to his former territory.", idiomatic: "\" Administrator of Longxi Zhang Yu released him. The Qiang at once dispersed and each returned to his former territory." },
  { zh: "迷吾退居河北歸義城。", literal: "Mi Wu withdrew to dwell north of the river at Guiyi city.", idiomatic: "Mi Wu withdrew to Guiyi city north of the river." },
  { zh: "疏勒王忠從康居王借兵，還據損中，遣使詐降於班超，超知其奸而偽許之。", literal: "King Zhong of Shule borrowed troops from the King of Kangju, returned and held Sunzhong, and sent an envoy to feign surrender to Ban Chao. Chao knew his treachery and falsely assented.", idiomatic: "King Zhong of Shule borrowed troops from the King of Kangju, returned and held Sunzhong, and sent an envoy to feign surrender to Ban Chao. Chao knew his treachery and pretended to assent." },
  { zh: "忠從輕騎詣超，超斬之，因擊破其眾，南道遂通。", literal: "Zhong came with light cavalry to Chao; Chao beheaded him and thereupon struck and broke his host. The southern road was then open.", idiomatic: "Zhong came with light cavalry to Chao. Chao beheaded him, struck and broke his host, and the southern road was open." },
  { zh: "楚許太后薨。", literal: "Empress Dowager Xu of Chu died.", idiomatic: "Empress Dowager Xu of Chu died." },
  { zh: "詔改葬楚王英，追爵謚曰楚厲侯。", literal: "An edict ordered reburial of Prince Ying of Chu and posthumously enfeoffed him with the title Marquis Lì of Chu.", idiomatic: "An edict ordered reburial of Prince Ying of Chu and posthumously enfeoffed him as Marquis Li of Chu." },
  { zh: "帝以穎川郭躬為廷尉。", literal: "The emperor made Guo Gong of Yingchuan Commandant of Justice.", idiomatic: "The emperor made Guo Gong of Yingchuan Commandant of Justice." },
  { zh: "決獄斷刑，多依矜恕，條諸重文可從輕者四十一，奏之，事皆施行。", literal: "In deciding prison cases and passing sentence, they largely relied on compassionate forbearance; they listed forty-one severe statutes that might be applied lightly, memorialized them, and all were put into effect.", idiomatic: "In deciding cases and passing sentence, officials largely relied on compassionate forbearance. They listed forty-one severe statutes that might be applied more lightly, memorialized them, and all were put into effect." },
  { zh: "博士魯國曹褒上疏，以為「宜定文制，著成漢禮」，太常巢堪以為「一世大典，非褒所定，不可許。", literal: "Erudite Cao Bao of Lu submitted a memorial, holding that \"ritual texts ought to be fixed and Han rites written into form\"; Grand Master of Ceremonies Chao Kan held that \"a great canon for an age is not what Bao can fix—it cannot be permitted.", idiomatic: "Erudite Cao Bao of Lu submitted a memorial, arguing that \"ritual texts ought to be fixed and Han rites written into form.\" Grand Master of Ceremonies Chao Kan held that \"a great canon for an age is not what Bao can fix—it cannot be permitted.\"" },
  { zh: "」帝知諸儒拘攣，難與圖始，朝廷禮憲，宜以時立，乃拜褒侍中。", literal: "\" The emperor knew the various scholars were rigid and cramped, hard to plan beginnings with; court ritual and statutes ought to be established in season—he thereupon appointed Bao Attendant-in-Ordinary.", idiomatic: "\" The emperor knew the scholars were rigid and hard to enlist for a fresh start. Court ritual ought to be established in good time, so he appointed Bao Attendant-in-Ordinary." },
  { zh: "玄武司馬班固以為「宜廣集諸儒，共議得失。", literal: "Northern Palace Gate Major Ban Gu held that \"one ought broadly to gather the various scholars and jointly discuss gains and losses.", idiomatic: "Northern Palace Gate Major Ban Gu argued that \"the various scholars ought to be gathered broadly to discuss what works and what does not.\"" },
  { zh: "」帝曰：「諺言：『作捨道邊，三年不成。", literal: "\" The emperor said: \"A proverb runs: 'Building a house beside the road, three years and it is not done.", idiomatic: "\" The emperor said, \"A proverb runs, 'Build a house beside the road and three years pass without finishing it.\"" },
  { zh: "』會禮之家，名為聚訟，互生疑異，筆不得下，昔堯作《大章》，一夔足矣。", literal: "' Those who meet on ritual matters are called a gathering of lawsuits; they breed doubt and difference for one another, the brush cannot descend—of old when Yao made the Great Manifestation, one Kui sufficed.", idiomatic: "\" Those who meet on ritual are called a gathering of lawsuits. They breed doubt for one another and the brush cannot descend. Of old, when Yao composed the Great Manifestation, one Kui sufficed.\"" },
  { zh: "春，正月，帝召褒，授以叔孫通《漢儀》十二篇曰：「此制散略，多不合經，今宜依禮條正，使可施行。", literal: "In spring, the first month, the emperor summoned Bao and handed him the twelve chapters of Shusun Tong's Han Ceremonial, saying: \"This system is scattered and summary, much not matching the classics—now it should be rectified according to ritual articles so it may be put into practice.", idiomatic: "In spring, in the first month, the emperor summoned Bao and handed him the twelve chapters of Shusun Tong's Han Ceremonial, saying, \"This system is scattered and summary and much of it does not match the classics. Now it should be rectified according to ritual articles so it may be put into practice.\"" },
  { zh: "護羌校尉傅育欲伐燒當羌，為其新降，不欲出兵，乃募人斗諸羌、胡；", literal: "Colonel Protecting the Qiang Fu Yu wished to attack the Shaodang Qiang; because they had newly submitted, he did not wish to send troops out, and instead recruited men to fight the various Qiang and Hu;", idiomatic: "Colonel Protecting the Qiang Fu Yu wished to attack the Shaodang Qiang. Because they had newly submitted, he did not wish to send troops out and instead recruited men to fight the various Qiang and Hu;" },
  { zh: "羌、胡不肯，遂復叛出塞，更依迷吾。", literal: "the Qiang and Hu would not agree and thereupon rebelled again beyond the pass, again relying on Miwu.", idiomatic: "the Qiang and Hu refused, rebelled again beyond the pass, and once more followed Miwu." },
  { zh: "育請發諸郡兵數萬人共擊羌。", literal: "Yu requested that troops from the various commanderies, tens of thousands, be sent to strike the Qiang together.", idiomatic: "Yu requested that tens of thousands of troops from the commanderies be sent to strike the Qiang together." },
  { zh: "未及會，三月，育獨進軍。", literal: "Before they could join, in the third month Yu advanced alone.", idiomatic: "Before they could join, in the third month Yu advanced alone." },
  { zh: "迷吾聞之，徙廬落去。", literal: "Miwu heard of it and moved his camps away.", idiomatic: "When Miwu heard of it, he moved his camps away." },
  { zh: "育遣精騎三千窮追之，夜，至三兜谷，不設備，迷吾襲擊，大破之，殺育及吏士八百八十人。", literal: "Yu sent three thousand picked horsemen in desperate pursuit; at night they reached Sandou Valley, made no preparations, and Miwu raided them, routing them greatly, killing Yu and officials and soldiers eight hundred eighty.", idiomatic: "Yu sent three thousand picked horsemen in desperate pursuit. At night they reached Sandou Valley, took no precautions, and Miwu raided them, routing them and killing Yu and eight hundred eighty officials and soldiers." },
  { zh: "及諸郡兵到，羌遂引去。", literal: "When the troops from the various commanderies arrived, the Qiang thereupon withdrew.", idiomatic: "When the commandery troops arrived, the Qiang withdrew." },
  { zh: "詔以隴西太守張紆為校尉，將萬人屯臨羌。", literal: "An edict made Longxi Administrator Zhang Xian colonel, leading ten thousand men to encamp at Linqiang.", idiomatic: "An edict appointed Longxi Administrator Zhang Xian colonel and ordered him to lead ten thousand men to encamp at Linqiang." },
  { zh: "夏，六月，戊辰，司徒桓虞免。", literal: "In summer, the sixth month, on wuchen day, Minister of Education Huan Yu was removed.", idiomatic: "In summer, in the sixth month, on wuchen day, Minister of Education Huan Yu was dismissed." },
  { zh: "癸卯，以司空袁安為司徒，光祿勳任隗為司空。", literal: "On guimao day, Minister of Works Yuan An was made Minister of Education, and Household Minister Ren Kui was made Minister of Works.", idiomatic: "On guimao day, Minister of Works Yuan An was made Minister of Education, and Household Minister Ren Kui was made Minister of Works." },
  { zh: "隗，光之子也。", literal: "Kui was the son of Guang.", idiomatic: "Kui was the son of Guang." },
  { zh: "齊王晃及弟利侯剛，與母太姬更相誣告。", literal: "Prince Huang of Qi and his younger brother Marquis Gang of Li, with their mother the Grand Lady, repeatedly accused one another.", idiomatic: "Prince Huang of Qi and his younger brother Marquis Gang of Li, with their mother the Grand Lady, repeatedly accused one another." },
  { zh: "秋，七月，癸卯，詔貶晃爵為蕪湖侯，削剛戶三千，收太姬璽緩。", literal: "In autumn, the seventh month, on guimao day, an edict demoted Huang's rank to Marquis of Wuhu, cut Gang's households by three thousand, and seized the Grand Lady's seal and ribbon.", idiomatic: "In autumn, in the seventh month, on guimao day, an edict demoted Huang to Marquis of Wuhu, cut Gang's households by three thousand, and seized the Grand Lady's seal and ribbon." },
  { zh: "壬子，淮陽頃王昺薨。", literal: "On renzi day, Prince Bing of Huaiyang died.", idiomatic: "On renzi day, Prince Bing of Huaiyang died." },
  { zh: "鮮卑入左地，擊北匈奴，大破之，斬優留單于而還。", literal: "The Xianbei entered the Left Territory, struck the Northern Xiongnu, routed them greatly, beheaded Chanyu Youliu, and returned.", idiomatic: "The Xianbei entered the Left Territory, struck the Northern Xiongnu, routed them, beheaded Chanyu Youliu, and returned." },
  { zh: "羌豪迷吾復與諸種寇金城塞，張紆遣從事河內司馬防與戰於木乘谷。", literal: "The Qiang chieftain Miwu again with the various tribes raided the Jin Cheng frontier; Zhang Xian sent Attendant Sima Fang of Henei to fight them at Mucheng Valley.", idiomatic: "The Qiang chieftain Miwu again joined the tribes in raiding the Jin Cheng frontier. Zhang Xian sent Attendant Sima Fang of Henei to fight them at Mucheng Valley." },
  { zh: "迷吾兵敗走，因譯使欲降，紆納之。", literal: "Miwu was defeated and fled; through an interpreter envoy he wished to submit, and Xian accepted him.", idiomatic: "Miwu was defeated and fled. Through an interpreter he offered to submit, and Xian accepted him." },
  { zh: "迷吾將人眾詣臨羌，紆設兵大會，施毒酒中，伏兵殺其酋豪八百餘人，斬迷吾頭以祭傅育塚，復放兵擊其餘眾，斬獲數千人。", literal: "Miwu led his masses to Linqiang; Xian set troops in a great assembly, put poison in the wine, and with hidden troops killed more than eight hundred of their chieftains and nobles, cut off Miwu's head to sacrifice at Fu Yu's tomb, then again released troops to strike the rest of their masses, beheading and capturing several thousand.", idiomatic: "Miwu led his followers to Linqiang. Xian held a great assembly with troops in readiness, put poison in the wine, and with hidden troops killed more than eight hundred chieftains and nobles. He cut off Miwu's head to sacrifice at Fu Yu's tomb, then sent troops against the rest and beheaded and captured several thousand." },
  { zh: "迷吾子迷唐，與諸種解仇，結婚交質，據大、小榆谷以叛，種眾熾盛，張紆不能制。", literal: "Miwu's son Miwutang, with the various tribes settling grievances, formed marriage alliances and exchanged hostages, held Great and Little Elm Valleys in rebellion—the tribal masses flourished, and Zhang Xian could not control them.", idiomatic: "Miwu's son Miwutang settled grievances with the tribes, formed marriage alliances and exchanged hostages, and held Great and Little Elm Valleys in rebellion. The tribal masses grew strong and Zhang Xian could not control them." },
  { zh: "壬戌，詔以瑞物仍集，改元章和。", literal: "On renxu day, an edict, because auspicious things continued to gather, changed the era name to Zhanghe.", idiomatic: "On renxu day, an edict, because auspicious objects continued to appear, changed the era name to Zhanghe." },
  { zh: "是時，京師四方屢有嘉瑞，前後數百千，言事者鹹以為美。", literal: "At this time the capital and the four quarters repeatedly had fine omens, several hundred or thousand in succession; those who spoke on affairs all deemed it beautiful.", idiomatic: "At this time the capital and the four quarters repeatedly reported fine omens, several hundred or thousand in all. Those who spoke on affairs all praised them." },
  { zh: "而太尉掾平陵何敞獨惡之，謂宋由、袁安曰：「夫瑞應依德而至，災異緣政而生。", literal: "But the Grand Commandant's clerk He Chang of Pingling alone detested this and said to Song You and Yuan An: \"Auspicious responses depend on virtue to arrive; strange disasters arise from government.", idiomatic: "But the Grand Commandant's clerk He Chang of Pingling alone detested this and said to Song You and Yuan An, \"Auspicious responses come when virtue warrants them; strange disasters arise from government.\"" },
  { zh: "今異烏翔於殿屋，怪草生於庭際，不可不察！", literal: "Now strange birds fly in the hall roofs, and weird grass grows at the courtyard's edge—it cannot go unexamined!", idiomatic: "Now strange birds fly about the hall roofs and weird grass grows at the courtyard's edge. This cannot go unexamined!\"" },
  { zh: "」由、安懼不敢答。", literal: "\" You and An were afraid and did not dare reply.", idiomatic: "\" You and An were afraid and did not dare reply." },
  { zh: "八月，癸酉，帝南巡。", literal: "In the eighth month, on guiyou day, the emperor made a southern tour.", idiomatic: "In the eighth month, on guiyou day, the emperor made a southern tour." },
  { zh: "戊子，幸梁；", literal: "On wuzi day he visited Liang;", idiomatic: "On wuzi day he visited Liang;" },
  { zh: "乙未晦，幸沛。", literal: "on the last day of the month, yiwei, he visited Pei.", idiomatic: "on the last day of the month, yiwei, he visited Pei." },
  { zh: "日有食之。", literal: "The sun suffered an eclipse.", idiomatic: "There was a solar eclipse." },
  { zh: "九月，庚子，帝幸彭城。", literal: "In the ninth month, on gengzi day, the emperor visited Pengcheng.", idiomatic: "In the ninth month, on gengzi day, the emperor visited Pengcheng." },
  { zh: "辛亥，幸壽春；", literal: "On xinhai day he visited Shouchun;", idiomatic: "On xinhai day he visited Shouchun;" },
  { zh: "復封阜陵侯延為阜陵王。", literal: "he again enfeoffed Marquis Yan of Fuling as King of Fuling.", idiomatic: "he again enfeoffed Marquis Yan of Fuling as King of Fuling." },
  { zh: "己未，幸汝陰。", literal: "On jiwei day he visited Ruyin.", idiomatic: "On jiwei day he visited Ruyin." },
  { zh: "冬，十月，丙子，還宮。", literal: "In winter, the tenth month, on bingzi day, he returned to the palace.", idiomatic: "In winter, in the tenth month, on bingzi day, he returned to the palace." },
  { zh: "北匈奴大亂，屈蘭儲等五十八部、口二十八萬詣雲中、五原、朔方、北地降。", literal: "The Northern Xiongnu fell into great disorder; Qulan Chu and fifty-eight other divisions, mouths numbering two hundred eighty thousand, came to Yunzhong, Wuyuan, Shuofang, and Beidi to submit.", idiomatic: "The Northern Xiongnu fell into great disorder. Qulan Chu and fifty-eight other divisions, two hundred eighty thousand people in all, came to Yunzhong, Wuyuan, Shuofang, and Beidi to submit." },
  { zh: "曹褒依準舊典，雜以《五經》、《讖記》之文，撰次天子至於庶人冠、婚、吉、凶終始制度凡百五十篇，奏之。", literal: "Cao Bao, following old canons as standard and mixing in texts from the Five Classics and prognostication records, compiled in order rites from capping through marriage, auspice and misfortune, beginning to end, for the Son of Heaven down to the common man—one hundred fifty chapters in all—and memorialized them.", idiomatic: "Cao Bao, following old canons and drawing on the Five Classics and prognostication texts, compiled in order one hundred fifty chapters of rites from capping through marriage, auspice and misfortune, for the Son of Heaven down to the common man, and memorialized them." },
  { zh: "帝以眾論難一，故但納之，不復令有司平奏。", literal: "The emperor, because the many opinions were hard to unify, therefore only accepted them and did not again order the responsible offices to review and memorialize.", idiomatic: "Because opinions could not be unified, the emperor only accepted the work and did not again order the responsible offices to review and memorialize it." },
  { zh: "是歲，班超發於窴諸國兵共二萬五千人擊莎車，龜茲王發溫宿、姑墨、尉頭兵合五萬人救之。", literal: "This year Ban Chao mobilized troops from the states of Yutian and others, twenty-five thousand in all, to attack Yarkand; the King of Kucha mobilized troops from Wensu, Gumo, and Weitou, fifty thousand together, to rescue it.", idiomatic: "This year Ban Chao mobilized twenty-five thousand troops from Yutian and other states to attack Yarkand. The King of Kucha mobilized fifty thousand men from Wensu, Gumo, and Weitou to rescue it." },
  { zh: "超召將校乃於窴王議曰：「今兵少不敵，其計莫若各散去。", literal: "Chao summoned the generals and colonels and with the King of Yutian deliberated, saying: \"Now our troops are few and cannot match the enemy—the plan is none better than for each to disperse.", idiomatic: "Chao summoned his generals and colonels and deliberated with the King of Yutian, saying, \"Our troops are few and cannot match the enemy. The best plan is for each to disperse.\"" },
  { zh: "於窴從是而東，長史亦於此西歸，可須夜鼓聲而發。", literal: "Yutian from here goes east, and the Chief Clerk also from here returns west—we may wait for the night drum to sound before setting out.", idiomatic: "Yutian will go east from here and the Chief Clerk will return west from here. We may wait for the night drum before setting out.\"" },
  { zh: "」陰緩所得生口。", literal: "\" He secretly ordered those captured alive to be held back slowly.", idiomatic: "\" He secretly ordered the captives to be released only slowly." },
  { zh: "龜茲王聞之，大喜，自以萬騎於西界遮超，溫宿王將八千騎於東界徼於窴。", literal: "The King of Kucha heard of it and was greatly pleased; he himself with ten thousand horsemen blocked Chao on the western border, and the King of Wensu led eight thousand horsemen on the eastern border to intercept Yutian.", idiomatic: "The King of Kucha heard of it and was greatly pleased. He himself took ten thousand horsemen to block Chao on the western border, and the King of Wensu led eight thousand horsemen on the eastern border to intercept Yutian." },
  { zh: "超知二虜已出，密召諸部勒兵。", literal: "Chao knew the two enemies had gone out and secretly summoned the various divisions to muster troops.", idiomatic: "Chao knew both enemies had gone out and secretly summoned the divisions to muster troops." },
  { zh: "雞鳴，馳赴莎車營。", literal: "At cockcrow he galloped to the Yarkand camp.", idiomatic: "At cockcrow he galloped to the Yarkand camp." },
  { zh: "胡大驚亂，奔走，追斬五千餘級；", literal: "The Hu were greatly alarmed and in disorder, fleeing and running; in pursuit he cut more than five thousand heads;", idiomatic: "The Hu were thrown into great alarm and disorder and fled. In pursuit he cut more than five thousand heads;" },
  { zh: "莎車遂降，龜茲等因各退散。", literal: "Yarkand thereupon submitted, and Kucha and the others accordingly each withdrew and dispersed.", idiomatic: "Yarkand thereupon submitted, and Kucha and the others each withdrew and dispersed." },
  { zh: "自是威震西域。", literal: "From this his prestige shook the Western Regions.", idiomatic: "From this his prestige shook the Western Regions." },
  { zh: "春，正月，濟南王康、阜陵王延、中山王焉來朝。", literal: "In spring, the first month, Prince Kang of Jinan, Prince Yan of Fuling, and Prince Yan of Zhongshan came to court.", idiomatic: "In spring, in the first month, Prince Kang of Jinan, Prince Yan of Fuling, and Prince Yan of Zhongshan came to court." },
  { zh: "上性寬仁，篤於親親，故叔父濟南、中山二王，每數入朝，特加恩寵，及諸昆弟並留京師，不遣就國。", literal: "The emperor by nature was generous and humane, deep in affection for kin; therefore his paternal uncles, the two kings of Jinan and Zhongshan, repeatedly came to court and received special favor and grace, and all his brothers and cousins alike were kept in the capital and not sent to their states.", idiomatic: "The emperor was generous and humane by nature and deep in affection for kin. Therefore his paternal uncles, the kings of Jinan and Zhongshan, came to court again and again and received special favor, and all his brothers and cousins were kept in the capital and not sent to their states." },
  { zh: "又賞賜群臣，過於制度，倉帑為虛。", literal: "He also rewarded and bestowed on the host of ministers beyond what regulation allowed, and the granaries and treasuries were emptied.", idiomatic: "He also rewarded the ministers beyond what regulation allowed, and the granaries and treasuries were emptied." },
  { zh: "何敞奏記宋由曰：「比年水旱，民不收穫。", literal: "He Chang submitted a note to Song You, saying: \"In recent years flood and drought— the people harvest nothing.", idiomatic: "He Chang submitted a note to Song You, saying, \"In recent years floods and droughts have left the people with no harvest.\"" },
  { zh: "涼州緣邊，家被凶害；", literal: "Along the borders of Liangzhou, households suffer deadly harm;", idiomatic: "Along the borders of Liangzhou households suffer deadly harm;" },
  { zh: "中州內郡，公私屈竭。", literal: "in the central provinces and inner commanderies, public and private are bent and exhausted.", idiomatic: "in the central provinces and inner commanderies public and private resources are exhausted." },
  { zh: "此實損膳節用之時，國恩覆載，賞賚過度，但聞臘賜，自郎官以上，公卿、王侯以下，至於空竭帑藏，損耗國資。", literal: "This is truly a time to reduce meals and economize expenditure. The state's grace covers and bears all, yet rewards and gifts exceed measure—one only hears of the year-end bestowals, from Gentlemen-of-the-Palace upward, from ministers and dukes and kings and marquises downward, until the treasury stores are emptied and state resources drained.", idiomatic: "This is truly a time to eat sparingly and economize. The state's grace covers all, yet rewards and gifts exceed measure. One hears only of the year-end bestowals, from Gentlemen-of-the-Palace upward and from ministers, dukes, kings, and marquises downward, until the treasury is emptied and state resources drained." },
  { zh: "尋公家之用，皆百姓之力。", literal: "Consider that what the public household uses is all the common people's strength.", idiomatic: "Remember that what the public household spends is the common people's strength." },
  { zh: "明君賜賚，宜有品制；", literal: "An enlightened ruler's gifts and grants ought to have grades and regulation;", idiomatic: "An enlightened ruler's gifts ought to have grades and regulation;" },
  { zh: "忠臣受賞，亦應有度。", literal: "a loyal minister receiving reward should also have measure.", idiomatic: "and a loyal minister receiving reward should also have measure." },
  { zh: "是以夏禹玄圭，周公束帛。", literal: "Therefore Yu of Xia had the dark jade tablet, and the Duke of Zhou had bundled silks.", idiomatic: "Therefore Yu of Xia received the dark jade tablet and the Duke of Zhou received bundled silks." },
  { zh: "今明公位尊任重，責深負大，上當匡正綱紀，下當濟安元元，豈但空空無違而已哉！", literal: "Now, eminent sir, your position is honored and your burden heavy, your responsibility deep and your charge great—above you ought to rectify the laws and statutes, below to succor and settle the common folk. How could it be only to be empty and without violation!", idiomatic: "Now, eminent sir, your position is honored and your burden heavy. Above, you ought to rectify the laws and statutes; below, to succor the common folk. How could it be enough merely to avoid violation!" },
  { zh: "宜先正己以率群下，還所得賜，因陳得失，奏王侯就國，除苑囿之禁，節省浮費，賑恤窮孤，則恩澤下暢，黎庶悅豫矣。", literal: "You ought first to rectify yourself to lead the host below, return what you have received in gifts, then set forth gains and losses, memorialize that kings and marquises go to their states, remove prohibitions on parks and preserves, economize floating expenditure, and relieve the poor and orphaned—then grace will flow below and the black-haired people will be pleased and at ease.", idiomatic: "You ought first to rectify yourself to lead those below, return what you have received in gifts, set forth what is wrong and what is right, memorialize that kings and marquises go to their states, remove prohibitions on parks and preserves, economize wasteful spending, and relieve the poor and orphaned. Then grace will flow below and the people will be pleased." },
  { zh: "」由不能用。", literal: "\" You could not employ this.", idiomatic: "\" You could not employ this." },
  { zh: "尚書南陽宋意上疏曰：「陛下至孝烝烝，恩家隆深，禮寵諸王，同之家人，車入殿門，即席不拜，分甘損膳，賞賜優渥。", literal: "Master of Writing Song Yi of Nanyang submitted a memorial: \"Your Majesty's utmost filial piety is abundant, family grace lofty and deep; in ritual you favor the various kings as one family—carriages enter the palace gate, they take their seats without bowing, you share sweetness and reduce your meals, rewards and gifts generous and thick.", idiomatic: "Master of Writing Song Yi of Nanyang submitted a memorial: \"Your Majesty's filial piety is abundant and family grace lofty and deep. In ritual you favor the various kings as one family. Their carriages enter the palace gate, they take their seats without bowing, you share your food and reduce your meals, and your rewards and gifts are generous.\"" },
  { zh: "康、焉幸以支庶，享食大國，陛下恩寵逾制，禮敬過度。", literal: "Kang and Yan, fortunate as collateral lines, enjoy the great states' sustenance—Your Majesty's grace and favor exceed regulation, ritual respect exceeds measure.", idiomatic: "Kang and Yan, fortunate as collateral lines, enjoy great states. Your Majesty's grace and favor exceed regulation and ritual respect exceeds measure.\"" },
  { zh: "《春秋》之義，諸父、昆弟，無所不臣，所以尊尊卑卑，強幹弱枝者也。", literal: "The meaning of the Spring and Autumn is that fathers' generation and brothers, none are not subjects—this is to honor the honored and abase the abased, strengthen the trunk and weaken the branches.", idiomatic: "\"The meaning of the Spring and Autumn is that uncles and brothers are all subjects. This is how one honors the honored and abases the abased and strengthens the trunk while weakening the branches.\"" },
  { zh: "陛下德業隆盛，當為萬世典法，不宜以私恩損上下之序，失君臣之正。", literal: "Your Majesty's virtue and achievement are lofty and flourishing—you ought to be the model law for ten thousand generations; it is not fitting to diminish the order of above and below through private affection and lose the correctness of ruler and minister.", idiomatic: "Your Majesty's virtue and achievement are lofty and flourishing. You ought to be the model law for ten thousand generations. It is not fitting to diminish the order of above and below through private affection or lose the correctness of ruler and minister.\"" },
  { zh: "又西平王羨等六王，皆妻子成家，官屬備具，當早就蕃國，為子孫基址；", literal: "Moreover the six kings including Prince Xian of Xiping all have wives and children who have formed households, officials and attendants complete—they ought early to go to their frontier states and lay foundations for their descendants;", idiomatic: "Moreover the six kings including Prince Xian of Xiping all have wives and children who have formed households and full staffs of officials. They ought early to go to their frontier states and lay foundations for their descendants;\"" },
  { zh: "而室第相望，久磐京邑，驕奢僭擬，寵祿隆過。", literal: "yet their mansions and lodges face one another, long settled in the capital, arrogant and extravagant beyond measure, favor and salary lofty and excessive.", idiomatic: "yet their mansions face one another, long settled in the capital, arrogant and extravagant beyond measure, with favor and salary excessive.\"" },
  { zh: "宜割情不忍，以義斷恩，發遣康、焉，各歸蕃國，令羨等速就便時，以塞眾望。", literal: "It is fitting to cut off affection one cannot bear and with righteousness sever grace—send Kang and Yan away, each to return to his frontier state, and order Xian and the others quickly to take the convenient season, to satisfy the multitude's expectation.", idiomatic: "It is fitting to cut off affection one cannot bear and with righteousness sever grace. Send Kang and Yan away, each to his frontier state, and order Xian and the others to go quickly at the proper season, to satisfy public expectation.\"" },
  { zh: "」帝未及遣。", literal: "\" The emperor had not yet reached sending them away.", idiomatic: "\" The emperor had not yet sent them away." },
  { zh: "壬辰，帝崩於章德前殿，年三十一。", literal: "On renchen day the emperor died in the Zhangde Front Hall, aged thirty-one.", idiomatic: "On renchen day the emperor died in the Zhangde Front Hall, aged thirty-one." },
  { zh: "遣詔：「無起寢廟，一如先帝法制。", literal: "His testamentary edict: \"Do not raise sleeping temples—altogether follow the former emperor's regulations.", idiomatic: "His testamentary edict ran, \"Do not raise sleeping temples. Follow altogether the late emperor's regulations.\"" },
  { zh: "范曄論曰：魏文帝稱明帝察察，章帝長者。", literal: "Fan Ye's commentary says: Emperor Wen of Wei called Emperor Ming perspicacious, and Emperor Zhang a man of mature years.", idiomatic: "Fan Ye's commentary says: Emperor Wen of Wei called Emperor Ming perspicacious and Emperor Zhang a man of mature years." },
  { zh: "章帝素知人，厭明帝苛切，事從寬厚；", literal: "Emperor Zhang by nature knew men, detested Emperor Ming's harsh severity, and in affairs followed lenience and breadth;", idiomatic: "Emperor Zhang by nature knew men, detested Emperor Ming's harsh severity, and in affairs followed lenience;" },
  { zh: "奉承明德太后，盡心孝道；", literal: "he served and upheld the Bright Virtue Empress Dowager and exhausted his heart in filial piety;", idiomatic: "he served the Bright Virtue Empress Dowager and exhausted himself in filial piety;" },
  { zh: "平徭簡賦，而民賴其慶；", literal: "he leveled corvée and simplified levies, and the people relied on his blessing;", idiomatic: "he leveled corvée and simplified levies, and the people relied on his blessing;" },
  { zh: "又體之以忠恕，文之以禮樂。", literal: "he also embodied them in loyalty and forbearance and adorned them with ritual and music.", idiomatic: "he also embodied loyalty and forbearance and adorned his rule with ritual and music." },
  { zh: "謂之長者，不亦宜乎！", literal: "To call him a man of mature years—is it not fitting!", idiomatic: "To call him a man of mature years—is it not fitting!" },
  { zh: "太子即位，年十歲，尊皇后曰皇太后。", literal: "The heir apparent took the throne, aged ten; the empress was honored as empress dowager.", idiomatic: "The heir apparent took the throne at the age of ten, and the empress was honored as empress dowager." },
  { zh: "三月，丁酉，用遺詔徙西平王羨為陳王，六安王恭為彭城王。", literal: "In the third month, on dingyou day, by the testamentary edict Prince Xian of Xiping was moved to be King of Chen, and Prince Gong of Lu'an was moved to be King of Pengcheng.", idiomatic: "In the third month, on dingyou day, by the testamentary edict Prince Xian of Xiping was moved to King of Chen and Prince Gong of Lu'an to King of Pengcheng." },
  { zh: "癸卯，葬孝章皇帝於敬陵。", literal: "On guimao day the Filial and Martial Emperor Zhang was buried at Jing Mausoleum.", idiomatic: "On guimao day the Filial and Martial Emperor Zhang was buried at Jing Mausoleum." },
  { zh: "南單于宣死，單于長之弟屯屠何立，為休蘭屍逐侯鞮單于。", literal: "The Southern Chanyu Xuan died; Chanyu Chang's younger brother Tuntuhe was established as Chanyu Xiulanshizhuhou Di.", idiomatic: "The Southern Chanyu Xuan died. Chanyu Chang's younger brother Tuntuhe was established as Chanyu Xiulanshizhuhou Di." },
  { zh: "太后臨朝，竇憲以侍中內干機密，出宣誥命；", literal: "The empress dowager held court; Dou Xian as Attendant-in-Ordinary inwardly handled secret affairs and outwardly proclaimed edicts and orders;", idiomatic: "The empress dowager held court. Dou Xian as Attendant-in-Ordinary handled secret affairs within and proclaimed edicts and orders without;" },
  { zh: "弟篤為虎賁中郎將，篤弟景、瓌並為中常侍，兄弟皆在親要之地。", literal: "his younger brother Du was Rapid-as-Tigers Colonel of the Palace Guard, Du's younger brothers Jing and Gui were both Regular Palace Attendants—the brothers were all in intimate and crucial posts.", idiomatic: "his younger brother Du was Rapid-as-Tigers Colonel of the Palace Guard, Du's younger brothers Jing and Gui were both Regular Palace Attendants, and the brothers all held intimate and crucial posts." },
  { zh: "憲客崔駰以書戒憲曰：「《傳》曰：『生而富者驕，生而貴者傲。", literal: "Xian's client Cui Yin admonished Xian in a letter, saying: \"The Tradition says: 'Those born rich are arrogant, those born noble are proud.", idiomatic: "Xian's client Cui Yin admonished Xian in a letter, saying, \"The Tradition says, 'Those born rich are arrogant, those born noble are proud.\"" },
  { zh: "』生富貴而能不驕傲者，未之有也。", literal: "' To be born rich and noble yet not be arrogant and proud—there has never been such.", idiomatic: "\" To be born rich and noble yet not be arrogant and proud—there has never been such.\"" },
  { zh: "今寵祿初隆，百僚觀行，豈可不庶幾夙夜，以永終譽乎！", literal: "Now favor and salary are newly lofty, the hundred officials watch your conduct—how could you not hope to emulate earnest vigil day and night, to secure lasting praise!", idiomatic: "Now favor and salary are newly lofty and the hundred officials watch your conduct. How could you not strive day and night to secure lasting praise!\"" },
  { zh: "昔馮野王以外戚居位，稱為賢臣；", literal: "Of old Feng Yewang, as maternal kin holding office, was called a worthy minister;", idiomatic: "Of old Feng Yewang, as maternal kin holding office, was called a worthy minister;\"" },
  { zh: "近陰衛尉克己復禮，終受多福。", literal: "recently the Commandant of the Guards Yin restrained himself and returned to ritual, and in the end received much blessing.", idiomatic: "recently Commandant of the Guards Yin restrained himself and returned to ritual, and in the end received much blessing.\"" },
  { zh: "外戚所以獲譏於時，垂愆於後者，蓋在滿而不挹，位有餘而仁不足也。", literal: "The reason maternal kin receive ridicule in their time and leave fault for later ages is broadly that when full they do not pour out, when position has surplus benevolence is insufficient.", idiomatic: "The reason maternal kin are ridiculed in their time and leave fault for later ages is broadly that when full they do not pour out and when position has surplus benevolence is insufficient.\"" },
  { zh: "漢興以後，迄於哀、平，外家二十，保族全身，四人而已。", literal: "From Han's rise down to Ai and Ping, maternal clans numbered twenty—those who preserved clan and kept body whole were four only.", idiomatic: "From Han's rise down to Ai and Ping, maternal clans numbered twenty. Those who preserved clan and body were four only.\"" },
  { zh: "《書》曰：『鑒於有殷，』可不慎哉！", literal: "The Documents says: 'Take warning from Yin'—how could one not be cautious!", idiomatic: "\"The Documents says, 'Take warning from Yin.' How could one not be cautious!\"" },
  { zh: "庚戌，皇太后詔：「以故太尉鄧彪為太傅，賜爵關內侯，錄尚書事，百官總己以聽。", literal: "On gengxu day the empress dowager edicted: \"Make the former Grand Commandant Deng Biao Grand Tutor, grant the title Marquis within the Passes, record affairs of the Masters of Writing, and let the hundred officials gather themselves to him to hear.", idiomatic: "On gengxu day the empress dowager edicted, \"Make the former Grand Commandant Deng Biao Grand Tutor, grant him the title Marquis within the Passes, record affairs of the Masters of Writing, and let the hundred officials gather themselves to hear him.\"" },
  { zh: "」竇憲以彪有義讓，先帝所敬，而仁厚委隨，故尊崇之。", literal: "\" Dou Xian, because Biao had righteous yielding, was what the former emperor respected, and was humane, generous, yielding, and easygoing, therefore honored and elevated him.", idiomatic: "\" Dou Xian, because Biao was righteous and yielding, was respected by the late emperor, and was humane, generous, and easygoing, therefore honored and elevated him." },
  { zh: "其所施為，輒外令彪奏，內白太后，事無不從。", literal: "Whatever he undertook to do, he would outwardly have Biao memorialize and inwardly inform the empress dowager—nothing was not followed.", idiomatic: "Whatever he undertook, he would outwardly have Biao memorialize and inwardly inform the empress dowager. Nothing failed to be followed." },
  { zh: "彪在位，修身而已，不能有所匡正。", literal: "Biao in office only cultivated himself and could not correct anything.", idiomatic: "While in office Biao only cultivated himself and could not correct anything." },
  { zh: "憲性果急，睚眥之怨，莫不報復。", literal: "Xian's nature was fierce and quick; grudges over a trifle—none went unavenged.", idiomatic: "Xian was fierce and quick-tempered; he avenged every trifling grudge." },
  { zh: "永平時，謁者韓紆考劾憲父勳獄，憲遂令客斬紆子，以首祭勳塚。", literal: "In the Yongping era, Gentleman-in-Attendance Han Xu investigated the prison case of Xian's father Xun; Xian thereupon had a retainer behead Xu's son and used the head to sacrifice at Xun's tomb.", idiomatic: "In the Yongping era Gentleman-in-Attendance Han Xu investigated the prison case of Xian's father Xun; Xian had a retainer behead Xu's son and offer the head at Xun's tomb." },
  { zh: "癸亥，陳王羨、彭城王恭、樂成王黨、下邳王衍、梁王暢始就國。", literal: "On guihai, King Xian of Chen, King Gong of Pengcheng, King Dang of Lecheng, King Yan of Xiapi, and King Chang of Liang first went to their states.", idiomatic: "On guihai day, King Xian of Chen, King Gong of Pengcheng, King Dang of Lecheng, King Yan of Xiapi, and King Chang of Liang first departed for their fiefs." },
  { zh: "夏，四月，戊寅，以遺詔罷郡國鹽鐵之禁，縱民煮鑄。", literal: "In summer, the fourth month, on wuyin, by the late emperor's testament abolished the prohibition on salt and iron in commanderies and kingdoms and let the people boil and cast freely.", idiomatic: "In summer, in the fourth month, on wuyin day, by the late emperor's testament the prohibition on commandery and kingdom salt and iron was lifted and the people were allowed to boil and cast freely." },
  { zh: "五月，京師旱。", literal: "In the fifth month, the capital suffered drought.", idiomatic: "In the fifth month there was drought in the capital." },
  { zh: "北匈奴饑亂，降南部者歲數千人。", literal: "The Northern Xiongnu suffered famine and disorder; those surrendering to the Southern Division numbered several thousand each year.", idiomatic: "The Northern Xiongnu suffered famine and disorder, and several thousand surrendered to the Southern Division each year." },
  { zh: "秋，七月，南單于上言：「宜及北虜分爭，出兵討伐，破北成南，並為一國，令漢家長無北念。", literal: "In autumn, the seventh month, the Southern Chanyu submitted: \"It is fitting, while the Northern barbarians are divided in strife, to send troops to attack and destroy the north to make the south, uniting as one state, so that the House of Han may forever be without northern cares.\"", idiomatic: "In autumn, in the seventh month, the Southern Chanyu memorialized, \"We should strike while the Northern barbarians are divided, send troops to attack, destroy the north and unite it with the south into one realm, so that Han may forever be free of northern worries.\"" },
  { zh: "臣等生長漢地，開口仰食，歲時賞賜，動輒億萬，雖垂拱安枕，慚無報效之義，願發國中及諸部故胡新降精兵，分道並出，期十二月同會虜地。", literal: "\"Your servants were raised in Han territory, open our mouths and look up to be fed; seasonal rewards often reach hundreds of millions—though we might fold our arms and rest on pillows, we are ashamed at having no duty of repayment; we wish to mobilize elite troops of the state and all divisions, old Hu and newly surrendered, to march out on separate routes and meet in barbarian territory in the twelfth month.\"", idiomatic: "\"We were raised on Han soil and live on imperial bounty; seasonal gifts often run to hundreds of millions. Though we might rest at ease, we are ashamed to repay nothing. We ask to mobilize elite troops of our state and all divisions, old Hu and newly surrendered alike, to march out on separate routes and rendezvous in Xiongnu territory in the twelfth month.\"" },
  { zh: "臣兵眾單少，不足以防內外，願遣執金吾耿秉、度遼將軍鄧鴻及西河、雲中、五原、朔方、上郡太守並力而北。", literal: "\"Your servants' forces are few and thin, insufficient to guard inside and outside; we wish to send Bearer of the Mace Geng Bing, General Who Crosses the Liao Deng Hong, and the administrators of Xihe, Yunzhong, Wuyuan, Shuofang, and Shang to join strength and go north.\"", idiomatic: "\"Our forces are too few to guard both within and without. We ask that Bearer of the Mace Geng Bing, General Who Crosses the Liao Deng Hong, and the administrators of Xihe, Yunzhong, Wuyuan, Shuofang, and Shang join forces and march north.\"" },
  { zh: "冀因聖帝威神，一舉平定。", literal: "\"We hope by the sage emperor's awesome spirit to pacify them in one stroke.\"", idiomatic: "\"We hope by the sage emperor's awesome power to pacify them at one stroke.\"" },
  { zh: "臣國成敗，要在今年，已敕諸部嚴兵馬，唯裁哀省察！", literal: "\"Our state's success or failure hinges on this year; we have already ordered all divisions to ready troops and horses—only grant compassionate review!\"", idiomatic: "\"Our state's fate hinges on this year. We have already ordered all divisions to ready troops and horses—only grant your compassionate approval!\"" },
  { zh: "」太后以示耿秉。", literal: "\" The empress dowager showed it to Geng Bing.", idiomatic: "\" The empress dowager showed the memorial to Geng Bing." },
  { zh: "秉上言：「昔武帝單極天下，欲臣虜匈奴，未遇天時，事遂無成。", literal: "Bing submitted: \"Formerly Emperor Wu alone exhausted all under heaven and wished to make the Xiongnu his subjects; he did not meet heaven's season, and the affair thus failed.\"", idiomatic: "Bing memorialized, \"Formerly Emperor Wu exhausted all under heaven and wished to make the Xiongnu his subjects, but heaven's season was not right and the affair failed.\"" },
  { zh: "今幸遭天授，北虜分爭，以夷伐夷，國家之利，宜可聽許。", literal: "\"Now we are fortunate to receive heaven's gift: the Northern barbarians are divided in strife—using barbarians to attack barbarians is the state's profit; it is fitting to hear and permit.\"", idiomatic: "\"Now heaven has granted us the chance: the Northern barbarians are divided. Using barbarians to fight barbarians profits the state. We should grant the request.\"" },
  { zh: "秉因自陳受恩，分當出命效用。", literal: "Bing thereupon declared himself indebted for favor and that it was his portion to go forth and expend his life in service.", idiomatic: "Bing thereupon declared that he owed imperial favor and that it was his duty to go forth and give his life in service." },
  { zh: "太后議欲從之。", literal: "The empress dowager deliberated and wished to follow it.", idiomatic: "The empress dowager deliberated and was inclined to agree." },
  { zh: "尚書宋意上書曰：「夫戎狄簡賤禮義，無有上下，強者為雄，弱即屈服。", literal: "Secretary Song Yi submitted: \"The Rong and Di hold ritual and righteousness cheap and slight; they have no superior and inferior—the strong become hegemon, the weak at once submit.\"", idiomatic: "Secretary Song Yi memorialized, \"The Rong and Di hold ritual and righteousness cheap. They know no superior and inferior—the strong rule and the weak submit.\"" },
  { zh: "自漢興以來，征伐數矣。", literal: "\"Since Han rose, campaigns and attacks have been numerous.\"", idiomatic: "\"Since Han rose, campaigns have been numerous.\"" },
  { zh: "其所克獲，曾不補害。", literal: "\"What was conquered and taken never made up the harm.\"", idiomatic: "\"What was conquered never made up the harm done.\"" },
  { zh: "光武皇帝躬服金革之難，深昭天地之明，故因其來降，羈縻畜養，邊民得生，勞役休息，於茲四十餘年矣。", literal: "\"Emperor Guangwu personally bore the hardship of arms and armor and deeply manifested heaven and earth's clarity; therefore, because they came to surrender, he bridled and fed them, border people obtained life, corvée rested—this has been more than forty years.\"", idiomatic: "\"Emperor Guangwu personally bore the hardships of war and deeply understood heaven and earth's will. He bridled and nurtured those who surrendered, so border people lived and corvée rested—for more than forty years now.\"" },
  { zh: "今鮮卑奉順，斬獲萬數，中國坐享大功，而百姓不知其勞。", literal: "\"Now the Xianbei submit in obedience, beheadings and captures number in the tens of thousands; the central states sit and enjoy great achievement while the common people do not know their toil.\"", idiomatic: "\"Now the Xianbei submit, and their kills and captures number in the tens of thousands. The central provinces enjoy great achievement while the people know no toil.\"" },
  { zh: "漢興功烈，於斯為盛。", literal: "\"Han since its rise—meritorious achievement has never been greater than now.\"", idiomatic: "\"Since Han rose, its achievements have never been greater than now.\"" },
  { zh: "所以然者，夷虜相攻，無損漢兵者也。", literal: "\"The reason is that barbarians and captives attack one another without harming Han troops.\"", idiomatic: "\"The reason is that barbarians fight one another without costing Han troops.\"" },
  { zh: "臣察鮮卑侵伐匈奴，正是利其抄掠；", literal: "\"Your servant observes that the Xianbei invading and attacking the Xiongnu are precisely profiting from their plundering raids;\"", idiomatic: "\"Your servant sees that when the Xianbei attack the Xiongnu they profit from plunder;\"" },
  { zh: "及歸功聖朝，實由貪得重賞。", literal: "\"when they attribute merit to the sage court, it is truly because they greedily obtain heavy rewards.\"", idiomatic: "\"and when they credit the sage court, it is truly because they greedily seek heavy rewards.\"" },
  { zh: "今若聽南虜還都北庭，則不得不禁制鮮卑。", literal: "\"Now if we hear the Southern captives and let them return their capital to the Northern Court, we cannot but restrain the Xianbei.\"", idiomatic: "\"If we now let the Southern Xiongnu return their capital to the Northern Court, we must restrain the Xianbei.\"" },
  { zh: "鮮卑外失暴掠之願，內無功勞之賞，豺狼貪婪，必為邊患。", literal: "\"The Xianbei outwardly lose the wish for violent plunder, inwardly lack rewards for merit—wolves greedy and rapacious will surely become border troubles.\"", idiomatic: "\"Deprived outwardly of plunder and inwardly of rewards for merit, the greedy Xianbei will surely become a border menace.\"" },
  { zh: "今北虜西遁，請求和親，宜因其歸附，以為外扞，巍巍之業，無以過此。", literal: "\"Now the Northern captives flee west and request peace marriage; it is fitting to take their submission as an outer shield—no grand enterprise surpasses this.\"", idiomatic: "\"Now the Northern Xiongnu flee west and seek peace marriage. We should take their submission as an outer shield—no grander policy exists.\"" },
  { zh: "若引兵費賦，以順南虜，則坐失上略，去安即危矣。", literal: "\"If we draw troops and spend taxes to follow the Southern captives, we sit and lose the superior strategy, leave security and approach danger.\"", idiomatic: "\"If we spend troops and taxes to follow the Southern Xiongnu, we abandon the superior strategy, leave security, and invite danger.\"" },
  { zh: "誠不可許。", literal: "\"Truly it must not be permitted.\"", idiomatic: "\"It truly must not be granted.\"" },
  { zh: "會齊殤王子都鄉侯暢來吊國憂，太后數召見之，竇憲懼暢分宮省之權，遣客刺殺暢於屯衛之中，而歸罪於暢弟利侯剛，乃使侍御史與青州刺史雜考剛等。", literal: "It happened that Marquis of Duxiang, Prince Chang of the late King of Qi, came to mourn the state's grief; the empress dowager repeatedly summoned him to audience; Dou Xian feared Chang would divide palace and ministry power, sent a retainer to assassinate Chang amid the encampment guards, and shifted blame to Chang's younger brother Marquis Gang of Li, then had Attendant Censor and Administrator of Qing jointly examine Gang and others.", idiomatic: "Marquis Chang of Duxiang, son of the late King of Qi, came to mourn the national bereavement. The empress dowager repeatedly summoned him. Dou Xian feared Chang would divide palace power and sent a retainer to assassinate him amid the encampment guards, then blamed Chang's younger brother Marquis Gang of Li and had an attendant censor and the Administrator of Qing jointly investigate Gang and others." },
  { zh: "尚書穎川韓稜以為「賊在京師，不宜捨近問遠，恐為奸臣所笑。", literal: "Secretary Han Ling of Yingchuan held that \"the culprit is in the capital—it is not fitting to abandon what is near and inquire afar, lest treacherous ministers laugh.\"", idiomatic: "Secretary Han Ling of Yingchuan held that \"the culprit is in the capital. We should not abandon what is near to inquire afar, lest treacherous ministers laugh.\"" },
  { zh: "」太后怒，以切責稜，稜固執其議。", literal: "\" The empress dowager was angry and sharply rebuked Ling; Ling firmly held to his view.", idiomatic: "\" The empress dowager was angry and sharply rebuked Ling, but Ling firmly held to his view." },
  { zh: "何敞說宋由曰：「暢宗室肺府，茅土籓臣，來吊大憂，上書須報，親在武衛，致此殘酷。", literal: "He Chang persuaded Song You, saying: \"Chang is the imperial clan's lung and belly, a fief-holding border minister who came to mourn the great grief, memorialized and awaited reply, kin within the martial guards—yet met this cruelty.\"", idiomatic: "He Chang urged Song You, saying, \"Chang is of the imperial clan's very core, a fief-holding border minister who came to mourn the great bereavement, memorialized and awaited reply, and was kin within the martial guards—yet met this cruelty.\"" },
  { zh: "奉憲之吏，莫適討捕，蹤跡不顯，主名不立。", literal: "\"The officials who serve Xian—none properly pursued and seized; tracks were not revealed, the chief name was not established.\"", idiomatic: "\"The officials who serve Xian made no proper pursuit. The trail was not revealed and the chief culprit was not named.\"" },
  { zh: "敞備數股肱，職典賊曹，欲親至發所，以糾其變。", literal: "\"Chang, ranked among the limbs and trunk, holds office over the bandit bureau and wishes personally to go to where it was uncovered to investigate the anomaly.\"", idiomatic: "\"Chang, ranked among the emperor's limbs, holds the bandit bureau and wishes to go personally to the scene to investigate the crime.\"" },
  { zh: "而二府執事以為故事：三公不與賊盜。", literal: "\"Yet the two offices' executors held it as precedent: the Three Excellencies do not deal with bandits and robbers.\"", idiomatic: "\"Yet the heads of the two offices held to precedent: the Three Excellencies do not handle bandits and robbers.\"" },
  { zh: "公縱奸慝，莫以為咎。", literal: "\"The excellencies indulge treachery and wickedness—none take it as fault.\"", idiomatic: "\"The excellencies indulge wickedness and none call it fault.\"" },
  { zh: "敞請獨奏案之。", literal: "\"Chang requests to memorialize alone and try the case.\"", idiomatic: "\"Chang asks to memorialize alone and try the case.\"" },
  { zh: "」由乃許焉。", literal: "\" You thereupon permitted it.", idiomatic: "\" You thereupon agreed." },
  { zh: "二府聞敞行，皆遣主者隨之。", literal: "The two offices, hearing Chang was going, all sent chief clerks to follow him.", idiomatic: "When the two offices heard Chang was going, each sent chief clerks to follow him." },
  { zh: "於是推舉，具得事實。", literal: "Thereupon through investigation the full facts were obtained.", idiomatic: "Through investigation the full facts were obtained." },
  { zh: "太后怒，閉憲於內宮。", literal: "The empress dowager was angry and confined Xian in the inner palace.", idiomatic: "The empress dowager was angry and confined Xian in the inner palace." },
  { zh: "憲懼誅，因自求擊匈奴以贖死。", literal: "Xian feared execution and thereupon begged himself to attack the Xiongnu to redeem death.", idiomatic: "Xian feared execution and begged to attack the Xiongnu to redeem his life." },
  { zh: "冬，十月，乙亥，以憲為車騎將軍，伐北匈奴，以執金吾耿秉為副。", literal: "In winter, the tenth month, on yihai, made Xian General of Chariots and Cavalry to attack the Northern Xiongnu, with Bearer of the Mace Geng Bing as deputy.", idiomatic: "In winter, in the tenth month, on yihai day, Xian was made General of Chariots and Cavalry to attack the Northern Xiongnu, with Bearer of the Mace Geng Bing as deputy." },
  { zh: "發北軍五校、黎陽、雍營、緣邊十二郡騎士及羌、胡兵出塞。", literal: "Mobilized the Northern Army's five colonels, Liyang, Yong camps, cavalry of twelve border commanderies, and Qiang and Hu troops beyond the pass.", idiomatic: "The Northern Army's five colonels, the Liyang and Yong camps, cavalry of twelve border commanderies, and Qiang and Hu troops were mobilized beyond the pass." },
  { zh: "公卿舉故張掖太守鄧訓代張紆為護羌校尉。", literal: "The excellencies and ministers recommended former Administrator of Zhangye Deng Xun to replace Zhang Xu as Protector of the Qiang.", idiomatic: "The excellencies recommended former Administrator of Zhangye Deng Xun to replace Zhang Xu as Protector of the Qiang." },
  { zh: "迷唐率兵萬騎來至塞下，未敢攻訓，先欲脅小月氏胡。", literal: "Mitang led ten thousand horsemen to the pass below but did not dare attack Xun; he first wished to coerce the Lesser Yuezhi Hu.", idiomatic: "Mitang led ten thousand horsemen to the frontier but did not dare attack Xun. He first tried to coerce the Lesser Yuezhi Hu." },
  { zh: "訓擁衛小月氏胡，令不得戰。", literal: "Xun shielded the Lesser Yuezhi Hu and would not let them fight.", idiomatic: "Xun shielded the Lesser Yuezhi Hu and would not let them fight." },
  { zh: "議者鹹以羌、胡相攻，縣官之利，不宜禁護。", literal: "Deliberators all held that Qiang and Hu attacking one another was profit for the magistrate's office—not fitting to forbid and protect.", idiomatic: "Counselors all held that letting Qiang and Hu fight one another profited the state and that protection should not be forbidden." },
  { zh: "訓曰：「張紆失信，眾羌大動，涼州吏民，命縣絲發。", literal: "Xun said: \"Zhang Xu lost faith; the Qiang masses were greatly stirred; the officials and people of Liang province hung by a thread of life.\"", idiomatic: "Xun said, \"Zhang Xu lost the people's trust and the Qiang rose in great unrest. The officials and people of Liang province hung by a thread.\"" },
  { zh: "原諸胡所以難得意者，皆恩信不厚耳。", literal: "\"The reason the various Hu are hard to win to one's will is all that favor and faith are not thick.\"", idiomatic: "\"The reason the various Hu are hard to win is simply that favor and faith are not deep.\"" },
  { zh: "今因其追急，以德懷之，庶能有用。", literal: "\"Now, while they press in urgency, embrace them with virtue—perhaps it can be of use.\"", idiomatic: "\"Now, while they press hard, we should win them with virtue—perhaps it will avail.\"" },
  { zh: "」遂令開城及所居園門，悉驅群胡妻子內之，嚴兵守衛。", literal: "\" He thereupon ordered the city gates and all garden gates where they dwelt opened, drove all the Hu groups' wives and children inside, and strictly guarded them with troops.", idiomatic: "\" He ordered the city gates and all dwelling-garden gates opened, brought all the Hu groups' wives and children inside, and guarded them strictly." },
  { zh: "羌掠無所得，又不敢逼諸胡，因即解去。", literal: "The Qiang plundered and obtained nothing, and again did not dare press the various Hu, so they dispersed and left.", idiomatic: "The Qiang plundered nothing, dared not press the various Hu, and withdrew." },
  { zh: "由是湟中諸胡皆言：「漢家常欲鬥我曹；", literal: "Thereby all the Hu of Huangzhong said: \"The House of Han always wished to make us fight one another;\"", idiomatic: "Thereupon all the Hu of Huangzhong said, \"The House of Han always wished to set us fighting one another;\"" },
  { zh: "今鄧使君待我以恩信，開門內我妻子，乃是得父母也！", literal: "\"now Commissioner Deng treats us with favor and faith, opens the gates and takes in our wives and children—this is truly gaining parents!\"", idiomatic: "\"but now Commissioner Deng treats us with favor and faith, opens the gates and takes in our wives and children—this is truly gaining parents!\"" },
  { zh: "」鹹歡喜叩頭曰：「唯使君所命！", literal: "\" All rejoiced, knocked their heads, and said: \"Only as the commissioner commands!\"", idiomatic: "\" All rejoiced, knocked their heads, and said, \"We obey only the commissioner's command!\"" },
  { zh: "」訓遂撫養教諭，小大莫不感悅。", literal: "\" Xun thereupon nurtured, taught, and instructed them; great and small none failed to be moved and pleased.", idiomatic: "\" Xun thereupon nurtured and instructed them, and great and small alike were moved and pleased." },
  { zh: "於是賞賂諸羌種，使相招誘，迷唐叔父號吾將其種人八百戶來降。", literal: "Thereupon he rewarded and bribed the various Qiang tribes, had them summon and entice one another; Mitang's uncle Haowu led eight hundred households of his tribe to surrender.", idiomatic: "Thereupon he rewarded the various Qiang tribes and had them summon one another. Mitang's uncle Haowu led eight hundred households of his tribe to surrender." },
  { zh: "訓因發湟中秦、胡、羌兵四千人出塞，掩擊迷唐於寫谷，破之，迷唐乃去大、小榆，居頗巖谷，眾悉離散。", literal: "Xun thereupon sent four thousand Qin, Hu, and Qiang troops of Huangzhong beyond the pass, surprised and struck Mitang at Xie Valley, defeated him; Mitang then left Great and Little Elm, dwelt at Poyan Valley, and his masses all scattered.", idiomatic: "Xun then sent four thousand Qin, Hu, and Qiang troops of Huangzhong beyond the pass, surprised Mitang at Xie Valley, and defeated him. Mitang left Great and Little Elm, moved to Poyan Valley, and his followers scattered." },
  { zh: "漢孝和皇帝上", literal: "Upper [reign segment] of Emperor Xiaohe of Han", idiomatic: "Emperor Xiaohe of Han — upper" },
  { zh: "春，迷唐欲復歸故地。", literal: "In spring, Mitang wished to return to his former territory.", idiomatic: "In spring Mitang wished to return to his former territory." },
  { zh: "鄧訓發湟中六千人，令長史任尚將之，縫革為船，置於箄上以渡河，掩擊迷唐，大破之，斬首前後一千八百餘級，獲生口二千人，馬牛羊三萬餘頭，一種殆盡。", literal: "Deng Xun sent six thousand men of Huangzhong, had Chief Clerk Ren Shang lead them, sewed leather into boats and set them on rafts to cross the river, surprised and struck Mitang, greatly defeated him—beheadings before and after totaled more than eighteen hundred, living captives two thousand, horses, cattle, and sheep more than thirty thousand head; one tribe was nearly exterminated.", idiomatic: "Deng Xun sent six thousand men of Huangzhong under Chief Clerk Ren Shang. They sewed leather into boats, set them on rafts to cross the river, surprised Mitang, and routed him. Beheadings totaled more than eighteen hundred, living captives two thousand, and more than thirty thousand horses, cattle, and sheep; one tribe was nearly wiped out." },
  { zh: "迷唐收其餘眾西徙千餘里，諸附落小種皆畔之。", literal: "Mitang gathered his remaining masses and moved west more than a thousand li; all attached settlements and lesser tribes rebelled against him.", idiomatic: "Mitang gathered his remnant forces and moved west more than a thousand li. All attached settlements and lesser tribes deserted him." },
  { zh: "燒當豪帥東號稽顙歸死，餘皆款塞納質。", literal: "The Shaodang chieftain Donghao knocked his forehead and came to surrender his life; the rest all sincerely opened the pass and offered hostages.", idiomatic: "The Shaodang chieftain Donghao knocked his forehead and surrendered himself. The rest all opened the pass and offered hostages." },
  { zh: "於是訓綏接歸附，威信大行，遂罷屯兵，各令歸郡，唯置弛刑徒二千餘人，分以屯田、修理塢壁而已。", literal: "Thereupon Xun soothed and received those who submitted; authority and trust greatly prevailed; he then dismissed garrison troops, ordered each to return to his commandery, and only placed more than two thousand men relieved from punishment to divide among colony fields and repair stockade walls—that was all.", idiomatic: "Thereupon Xun soothed the submitted tribes and his authority prevailed. He dismissed the garrison troops and sent each man back to his commandery, leaving only more than two thousand men relieved from punishment to farm colonies and repair stockade walls." },
  { zh: "竇憲將征匈奴，三公、九卿詣朝堂上書諫，以為：「匈奴不犯邊塞，而無故勞師遠涉，損費國用，徼功萬里，非社稷之計。", literal: "Dou Xian was about to campaign against the Xiongnu; the Three Excellencies and Nine Ministers went to the court hall and submitted remonstrance, holding: \"The Xiongnu do not violate the border passes, yet without cause we weary the army in distant ventures, harm state expenditure, and seek merit ten thousand li away—this is not a plan for the altars of soil and grain.\"", idiomatic: "As Dou Xian was about to campaign against the Xiongnu, the Three Excellencies and Nine Ministers went to the court hall and memorialized in remonstrance: \"The Xiongnu are not violating the frontier, yet without cause we weary the army on a distant expedition, drain the treasury, and seek merit ten thousand li away. This is no plan for the altars of state.\"" },
  { zh: "」書連上，輒寢，宋由懼，遂不敢復署議，而諸卿稍自引止。", literal: "\" Memorials were submitted in succession and at once shelved; Song You was afraid and thereupon did not dare again to countersign deliberations, while the various ministers gradually withdrew on their own.", idiomatic: "\" Memorials were submitted in succession and shelved. Song You grew afraid and dared not countersign further deliberations, and the various ministers gradually withdrew." },
  { zh: "唯袁安、任隗守正不移，至免冠朝堂固爭，前後且十上，眾皆為之危懼，安、隗正色自若。", literal: "Only Yuan An and Ren Wei held correctness unmoved, even removing their caps in the court hall and firmly disputing—before and after nearly ten submissions; the crowd all feared for them, yet An and Wei kept stern countenance as if at ease.", idiomatic: "Only Yuan An and Ren Wei held firm. They even removed their caps in court and disputed stubbornly, memorializing nearly ten times. All feared for them, yet An and Wei kept stern countenances as if at ease." },
  { zh: "侍御史魯恭上疏曰：「國家新遭大憂，陛下方在諒陰，百姓闕然，三時不聞警蹕之音，莫不懷思皇皇，若有求而不得。", literal: "Attendant Censor Lu Gong submitted: \"The state has newly suffered great grief; Your Majesty is just in the mourning hut; the common people are unsettled—through three seasons they have not heard the sound of the guard retinue; none fail to think longingly in urgency, as if seeking yet not obtaining.\"", idiomatic: "Attendant Censor Lu Gong memorialized, \"The state has newly suffered great grief. Your Majesty is still in mourning. The people are unsettled. For three seasons they have not heard the guard retinue. All think longingly in urgency, as if seeking yet not obtaining.\"" },
  { zh: "今乃以盛春之月興發軍役，擾動天下，以事戎夷，誠非所以垂恩中國，改元正時，由內及外也。", literal: "\"Now in the flourishing spring month you raise and dispatch military service, disturb all under heaven, and take affairs to the Rong and Yi—truly this is not the way to extend favor to the central states, correct the era and season, and proceed from within to without.\"", idiomatic: "\"Now in the height of spring you raise military service, disturb the realm, and take affairs to the barbarians. This is truly not how to extend favor to the central provinces, correct the era and season, and proceed from within outward.\"" },
  { zh: "萬民者，天之所生；", literal: "\"The ten thousand people are what heaven produces;\"", idiomatic: "\"The ten thousand people are what heaven produces;\"" },
  { zh: "天愛其所生，猶父母愛其子，一物有不得其所，則正氣為之舛錯，況於人乎！", literal: "\"heaven loves what it produces as parents love their children—if one thing does not obtain its place, then orthodox qi is thereby disordered; how much more for people!\"", idiomatic: "\"heaven loves what it produces as parents love their children. If one thing does not obtain its place, orthodox qi is disordered—how much more for people!\"" },
  { zh: "故愛民者必有天報。", literal: "\"Therefore those who love the people surely receive heaven's reward.\"", idiomatic: "\"Therefore those who love the people surely receive heaven's reward.\"" },
  { zh: "夫戎狄者，四方之異氣，與鳥獸無別；", literal: "\"The Rong and Di are strange qi of the four quarters, no different from birds and beasts;\"", idiomatic: "\"The Rong and Di are strange qi of the four quarters, no different from birds and beasts;\"" },
  { zh: "若雜居中國，則錯亂天氣，污辱善人，是以聖王之制，羈縻不絕而已。", literal: "\"if mixed within the central states they disorder heaven's qi and defile good people—therefore the sage kings' regulation is only to bridle and feed without cutting off.\"", idiomatic: "\"if mixed within the central states they disorder heaven's qi and defile good people. Therefore the sage kings' regulation is only to bridle and feed them without cutting them off.\"" },
  { zh: "今匈奴為鮮卑所破，遠藏於史侯河西，去塞數千里，而欲乘其虛耗，利其微弱，是非義之所出也。", literal: "\"Now the Xiongnu are broken by the Xianbei, hide far west of the Shiyu River, several thousand li from the passes—yet you wish to ride their emptiness and exhaustion and profit from their weakness; this is not where righteousness issues.\"", idiomatic: "\"Now the Xiongnu are broken by the Xianbei and hide far west of the Shiyu River, several thousand li from the frontier. To ride their exhaustion and profit from their weakness is not where righteousness lies.\"" },
  { zh: "今始征發，而大司農調度不足，上下相迫，民間之急，亦已甚矣。", literal: "\"Now at the first mobilization the Grand Minister of Agriculture's allocations are insufficient; above and below press one another—the people's urgency is already extreme.\"", idiomatic: "\"At the first mobilization the Grand Minister of Agriculture's allocations are already insufficient. Above and below press one another, and the people's distress is already extreme.\"" },
  { zh: "群僚百姓鹹曰不可，陛下獨奈何以一人之計，棄萬人之命，不恤其言乎！", literal: "\"All officials and the common people say it cannot be done—does Your Majesty alone, for one man's plan, abandon the lives of ten thousand people and not pity their words!\"", idiomatic: "\"All officials and the common people say it cannot be done. Will Your Majesty alone, for one man's plan, abandon the lives of ten thousand people and not heed their words!\"" },
  { zh: "上觀天心，下察人志，足以知事之得失。", literal: "\"Look above at heaven's heart, look below at men's will—sufficient to know the gain and loss of the affair.\"", idiomatic: "\"Look above at heaven's heart and below at men's will, and you will know the gain and loss of the affair.\"" },
  { zh: "臣恐中國不為中國，豈徒匈奴而已哉！", literal: "\"Your servant fears the central states will not remain the central states—is it only the Xiongnu!\"", idiomatic: "\"Your servant fears the central provinces will cease to be the central provinces—is it only a matter of the Xiongnu!\"" },
  { zh: "」尚書令韓稜、騎都尉朱暉、議郎京兆樂恢，皆上疏諫，太后不聽。", literal: "\" Secretary-in-Chief Han Ling, Commandant of Cavalry Zhu Hui, and Discussion Gentleman Yue Hui of Jingzhao all submitted remonstrance; the empress dowager did not listen.", idiomatic: "\" Secretary-in-Chief Han Ling, Commandant of Cavalry Zhu Hui, and Discussion Gentleman Yue Hui of Jingzhao all memorialized in remonstrance. The empress dowager would not listen." },
  { zh: "又詔使者為憲弟篤、景並起邸第，勞役百姓。", literal: "She also ordered envoys to build lodge mansions for Xian's younger brothers Du and Jing together, conscripting the common people in labor.", idiomatic: "She also ordered envoys to build lodge mansions for Xian's younger brothers Du and Jing, conscripting the people in labor." },
  { zh: "侍御史何敞上疏曰：「臣聞匈奴之為桀逆久矣，平城之圍，慢書之恥，此二辱者，臣子所謂捐軀而必死，高祖、呂後忍怒還忿，捨而不誅。", literal: "Attendant Censor He Chang submitted: \"Your servant has heard that the Xiongnu have been arrogant and rebellious for long; the siege of Pingcheng, the insult of the contemptuous letter—these two humiliations are what ministers and sons call giving the body and surely dying. The High Emperor and Empress Lü endured anger and returned resentment, released and did not punish.\"", idiomatic: "Attendant Censor He Chang memorialized, \"Your servant has heard that the Xiongnu have long been arrogant and rebellious. The siege of Pingcheng and the insult of the contemptuous letter are humiliations for which ministers should give their lives. The High Emperor and Empress Lü endured anger and did not punish.\"" },
  { zh: "今匈奴無逆節之罪，漢朝無可慚之恥，而盛春東作，興動大役，元元怨恨，鹹懷不悅。", literal: "\"Now the Xiongnu have no crime of rebellious conduct; the Han court has no humiliation to be ashamed of—yet in flourishing spring, when the east begins work, you raise and move great labor; the masses resent and all harbor displeasure.\"", idiomatic: "\"Now the Xiongnu have committed no crime of rebellion and the Han court has no humiliation to bear shame for—yet in flourishing spring, when eastern work begins, you raise great labor. The masses resent it and all are displeased.\"" },
  { zh: "又猥復為衛尉篤、奉車都尉景繕修館第，彌街絕裡。", literal: "\"Moreover you again improperly rebuild lodge mansions for Commandant of the Guards Du and Commandant of the Imperial Carriage Jing, filling the streets and cutting off lanes.\"", idiomatic: "\"Moreover you again improperly rebuild mansions for Commandant of the Guards Du and Commandant of the Imperial Carriage Jing, filling the streets and cutting off lanes.\"" },
  { zh: "篤、景親近貴臣，當為百僚表儀。", literal: "\"Du and Jing are close and honored ministers—they should be the hundred officials' model and standard.\"", idiomatic: "\"Du and Jing are close honored ministers. They should be models for the hundred officials.\"" },
  { zh: "今眾軍在道，朝廷焦脣，百姓愁苦，縣官無用，而遽起大第，崇飾玩好，非所以垂令德、示無窮也。", literal: "\"Now the mass of armies is on the road, the court is parched at the lips, the common people grieve in bitterness, the magistrate's office has no surplus—yet you hastily raise great mansions and exalt ornament and curios—this is not the way to extend command virtue and show the endless.\"", idiomatic: "\"Now the armies are on the march, the court is parched with worry, the people grieve, and the treasury has no surplus—yet you hastily raise great mansions and exalt ornament and curios. This is not how to extend commanding virtue and show what endures.\"" },
  { zh: "宜且罷工匠，專憂北邊，恤民之困。", literal: "\"It is fitting for now to stop craftsmen, focus worry on the northern border, and pity the people's distress.\"", idiomatic: "\"For now you should stop the craftsmen, focus on the northern border, and pity the people's distress.\"" },
  { zh: "」書奏，不省。", literal: "\" When the memorial was presented, it was not reviewed.", idiomatic: "\" When the memorial was presented, it was not heeded." },
  { zh: "竇憲嘗使門生繼書詣尚書僕射郅壽，有所請托，壽即送詔獄，前後上書，陳憲驕恣，引王莽以誡國家；", literal: "Dou Xian once sent a student retainer Ji Shu to Vice Director of the Masters of Writing Zhi Shou with a request for favor; Shou at once sent him to the imperial prison. Before and after he submitted memorials stating Xian's arrogance and license, citing Wang Mang to warn the state;", idiomatic: "Dou Xian once sent a student retainer Ji Shu to Vice Director of the Masters of Writing Zhi Shou with a request for favor. Shou at once sent him to the imperial prison. He repeatedly memorialized on Xian's arrogance and license, citing Wang Mang to warn the state;" },
  { zh: "又因朝會，刺譏憲等以伐匈奴、起第宅事，厲音正色，辭旨甚切。", literal: "he also at court assembly satirically reproached Xian and others over attacking the Xiongnu and raising mansions—severe in voice, upright in countenance, words and intent very cutting.", idiomatic: "and at court assembly he satirically reproached Xian and others over attacking the Xiongnu and raising mansions—severe in voice, upright in countenance, and very cutting in intent." },
  { zh: "憲怒，陷壽以買公田、誹謗，下吏，當誅，何敝上疏曰：「壽機密近臣，匡救為職，若懷默不言，其罪當誅。", literal: "Xian was angry, trapped Shou with buying public fields and slander, handed him to the law officers—due for execution. He Chang submitted: \"Shou is a confidential close minister; correction and rescue are his duty. If he harbored silence and did not speak, his crime would merit execution.\"", idiomatic: "Xian was angry, framed Shou on buying public fields and slander, and handed him to the law officers for execution. He Chang memorialized, \"Shou is a confidential close minister whose duty is correction and rescue. If he kept silent, his crime would merit execution.\"" },
  { zh: "今壽違眾正議以安宗廟，豈其私邪！", literal: "\"Now Shou opposed the crowd's view with upright deliberation to secure the ancestral temple—how could it be private!\"", idiomatic: "\"Now Shou opposed the crowd with upright deliberation to secure the ancestral temple. How could that be private!\"" },
  { zh: "臣所以觸死瞽言，非為壽也。", literal: "\"Your servant's reason for touching death and speaking blindly is not for Shou's sake.\"", idiomatic: "\"Your servant touches death and speaks blindly not for Shou's sake.\"" },
  { zh: "忠臣盡節，以死為歸；", literal: "\"Loyal ministers exhaust integrity and take death as their return;\"", idiomatic: "\"Loyal ministers exhaust their integrity and take death as their return;\"" },
  { zh: "臣雖不知壽，度其甘心安之。", literal: "\"your servant though not knowing Shou, estimates he would gladly rest in it.\"", idiomatic: "\"though your servant does not know Shou, I judge he would gladly accept it.\"" },
  { zh: "誠不欲聖朝行誹謗之誅，以傷晏晏之化，杜塞忠直，垂譏無窮。", literal: "\"Truly I do not wish the sage court to execute the punishment for slander, thereby harming the gentle and peaceful transformation, blocking loyal uprightness, and leaving ridicule without end.\"", idiomatic: "\"I truly do not wish the sage court to execute punishment for slander, thereby harming gentle governance, blocking loyal uprightness, and leaving endless ridicule.\"" },
  { zh: "臣敞謬與機密，言所不宜，罪名明白，當填牢獄，先壽僵仆，萬死有餘。", literal: "Your servant Chang wrongly participated in confidential affairs and spoke what was not fitting; the charge is clear and he ought to fill the prison—before Shou stiffened and fell, ten thousand deaths would not be enough.", idiomatic: "Your servant Chang wrongly participated in confidential affairs and spoke what was not fitting; the charge is clear and I ought to fill the prison—before Shou fell dead, ten thousand deaths would not have been enough." },
  { zh: "」書奏，壽得減死論，徙合浦，未行，自殺。", literal: "\" When the memorial was submitted, Shou received a reduced sentence from death and was banished to Hepu; before he set out he killed himself.", idiomatic: "\" When the memorial was submitted, Shou's death sentence was commuted to banishment in Hepu; before he departed he killed himself." },
  { zh: "壽，惲之子也。", literal: "Shou was the son of Yun.", idiomatic: "Shou was the son of Yang Yun." },
  { zh: "夏，六月，竇憲、耿秉出朔方雞鹿塞，南單于出滿夷谷，度遼將軍鄧鴻出□固陽塞，皆會涿邪山。", literal: "In summer, the sixth month, Dou Xian and Geng Bing went out through Shuofang's Jilu Pass, the Southern Shanyu went out through Manyi Valley, Crossing-General Deng Hong went out through [lacuna] Guyang Pass, and all met at Zhuoye Mountain.", idiomatic: "In summer, in the sixth month, Dou Xian and Geng Bing went out through Shuofang's Jilu Pass, the Southern Shanyu through Manyi Valley, and Crossing-General Deng Hong through Guyang Pass; all met at Zhuoye Mountain." },
  { zh: "憲分遣副校尉閻盤、司馬耿夔、耿譚將南匈奴精騎萬餘，與北單于戰於稽洛山，大破之，單于遁走。", literal: "Xian detached Vice Colonel Yan Pan, Major Geng Kui, and Geng Tan to lead more than ten thousand elite Southern Xiongnu horsemen; they fought the Northern Shanyu at Mount Jiluo, routed him greatly, and the Shanyu fled.", idiomatic: "Xian detached Vice Colonel Yan Pan and Majors Geng Kui and Geng Tan to lead more than ten thousand elite Southern Xiongnu horsemen; they fought the Northern Shanyu at Mount Jiluo, routed him utterly, and the Shanyu fled." },
  { zh: "追擊諸部，遂臨私渠北鞮海，斬名王以下萬三千級，獲生口甚眾，雜畜百餘萬頭，諸裨小王率眾降者，前後八十一部二十餘萬人。", literal: "Pursuing the various tribes, they then reached the Northern Di Sea of the Private Canal; they beheaded more than thirteen thousand down to titled kings, captured very many living captives, and over a million head of mixed livestock; various subordinate lesser kings who led their masses to surrender numbered in all eighty-one tribes and more than two hundred thousand people.", idiomatic: "Pursuing the various tribes, they reached the Northern Di Sea of the Private Canal, beheaded more than thirteen thousand down to titled kings, took vast numbers of captives, and seized over a million head of mixed livestock; subordinate lesser kings who led their people to surrender totaled eighty-one tribes and more than two hundred thousand people." },
  { zh: "憲、秉出塞三千餘里，登燕然山，命中護軍班固刻石勒功，紀漢威德而還。", literal: "Xian and Bing went beyond the frontier more than three thousand li, ascended Mount Yanran, ordered Central Protector of the Army Ban Gu to carve stone and inscribe merit, recording Han's power and virtue, and returned.", idiomatic: "Xian and Bing went beyond the frontier more than three thousand li, ascended Mount Yanran, ordered Central Protector of the Army Ban Gu to carve an inscription recording their achievement and Han's power and virtue, and returned." },
  { zh: "遣軍司馬吳汜、梁諷奉金帛遺北單于，時虜中乖亂，汜、諷及單于於西海上，宣國威信，以詔致賜，單于稽首拜受。", literal: "They sent Army Major Wu Si and Liang Feng bearing gold and silks to present to the Northern Shanyu; at the time the barbarians were in disorder within, and Si and Feng met the Shanyu on the Western Sea, proclaimed the state's authority and trust, and by imperial edict bestowed gifts; the Shanyu kowtowed and received them in obeisance.", idiomatic: "They sent Army Major Wu Si and Liang Feng with gold and silks for the Northern Shanyu; the barbarians were in internal disorder, and Si and Feng met the Shanyu on the Western Sea, proclaimed the state's authority, and by imperial edict bestowed gifts; the Shanyu kowtowed and received them." },
  { zh: "諷因說令修呼韓邪故事，單于喜悅，即將其眾與諷俱還；", literal: "Feng thereupon urged him to restore the precedent of Huhanye, the Shanyu was delighted, and at once led his masses back together with Feng;", idiomatic: "Feng urged him to restore the precedent of Huhanye; the Shanyu was delighted and at once led his people back with Feng;" },
  { zh: "到私渠海，聞漢軍已入塞，乃遣弟右溫禺鞮王奉貢入侍，隨諷詣闕。", literal: "reaching the Private Canal Sea they heard the Han army had already entered the passes, whereupon he sent his younger brother the Right Wenyu Di King to present tribute and attend at court, following Feng to the palace.", idiomatic: "reaching the Private Canal Sea they heard the Han army had already entered the passes, whereupon he sent his younger brother the Right Wenyu Di King to present tribute and attend at court, following Feng to the capital." },
  { zh: "憲以單于不自身到，奏還其侍弟。", literal: "Xian, because the Shanyu did not come in person, memorialized to send back his attending younger brother.", idiomatic: "Because the Shanyu did not come in person, Xian memorialized to send back his attending younger brother." },
  { zh: "秋，七月，乙未，會稽山崩。", literal: "In autumn, the seventh month, on yiwei, Mount Kuaiji collapsed.", idiomatic: "In autumn, in the seventh month, on yiwei day, Mount Kuaiji collapsed." },
  { zh: "九月，庚申，以竇憲為大將軍，中郎將劉尚為車騎將軍，封憲武陽侯，食邑二萬戶；", literal: "In the ninth month, on gengshen, Dou Xian was made Grand General and Gentlemen of the Palace Liu Shang was made General of Chariots and Cavalry; Xian was enfeoffed as Marquis of Wuyang with a fief of twenty thousand households;", idiomatic: "In the ninth month, on gengshen day, Dou Xian was made Grand General and Gentlemen of the Palace Liu Shang General of Chariots and Cavalry; Xian was enfeoffed as Marquis of Wuyang with a fief of twenty thousand households;" },
  { zh: "憲固辭封爵，詔許之。", literal: "Xian firmly declined enfeoffment and rank; an edict permitted it.", idiomatic: "Xian firmly declined the title and rank; an edict permitted it." },
  { zh: "舊，大將軍位在三公下，至是，詔憲位次太傅下、三公上；", literal: "Formerly the Grand General's position was below the Three Excellencies; to this point an edict placed Xian's rank below the Grand Tutor and above the Three Excellencies;", idiomatic: "Formerly the Grand General ranked below the Three Excellencies; now an edict placed Xian below the Grand Tutor and above the Three Excellencies;" },
  { zh: "長史、司馬秩中二千石。", literal: "Chief Clerk and Major held rank of two thousand bushels middle.", idiomatic: "his Chief Clerk and Major held middle two-thousand-bushel rank." },
  { zh: "封耿秉為美陽侯。", literal: "Geng Bing was enfeoffed as Marquis of Meiyang.", idiomatic: "Geng Bing was enfeoffed as Marquis of Meiyang." },
  { zh: "竇氏兄弟驕縱，而執金吾景尤甚，奴客緹騎強奪人財貨，篡取罪人，妻略婦女。", literal: "The Dou brothers were arrogant and unrestrained, but Commandant of the Imperial Carriages Jing was especially so; slaves, retainers, and mounted escorts forcibly seized people's goods and wealth, usurped and took condemned men, and took others' wives and violated women.", idiomatic: "The Dou brothers were arrogant and unrestrained, but Commandant of the Imperial Carriages Jing was worst of all; his slaves, retainers, and mounted escorts forcibly seized people's property, snatched condemned men, and abducted and violated women." },
  { zh: "商賈閉塞，如避寇仇。", literal: "Merchants were blocked and closed off as if avoiding bandits and foes.", idiomatic: "Merchants shut their doors as if avoiding bandits." },
  { zh: "又擅發緣邊諸郡突騎有才力者，有司莫敢舉奏，袁安劾景「擅發邊兵，驚惑吏民；", literal: "He also on his own authority mobilized swift riders of ability from the various frontier commanderies; the responsible offices did not dare memorialize against him. Yuan An impeached Jing: \"On his own authority mobilizing frontier troops, alarming and confusing officials and people;", idiomatic: "He also on his own authority mobilized able swift riders from the frontier commanderies; the responsible offices dared not memorialize against him. Yuan An impeached Jing, saying, \"On his own authority mobilizing frontier troops, alarming officials and people;" },
  { zh: "二千石不待符信而輒承景檄，當伏顯誅。", literal: "two-thousand-bushel officials who did not wait for tallies and credentials yet at once obeyed Jing's dispatch ought to suffer manifest execution.\"", idiomatic: "two-thousand-bushel officials who did not wait for tallies and credentials yet obeyed Jing's dispatch ought to suffer manifest execution.\"" },
  { zh: "」又奏「司隸校尉河南尹阿附貴戚，不舉劾，請免官案罪。", literal: "\" He also memorialized: \"The Director of the Secretariat Censor and Administrator of Henan toady to the noble kin and do not impeach—request dismissal from office and prosecution by charge.\"", idiomatic: "\" He also memorialized, \"The Director of the Secretariat Censor and the Administrator of Henan toady to the noble kin and fail to impeach—request their dismissal and prosecution.\"" },
  { zh: "」並寢不報。", literal: "\" Both were shelved without reply.", idiomatic: "\" Both memorials were shelved without reply." },
  { zh: "駙馬都尉瑰，獨好經書，節約自修。", literal: "Commandant of the Imperial Son-in-Law Gui alone loved the classics and was frugal in self-cultivation.", idiomatic: "Commandant of the Imperial Son-in-Law Gui alone loved the classics and cultivated frugality." },
  { zh: "尚書何敞上封事曰：「昔鄭武姜之幸叔段，衛莊公之寵州吁，愛而不教，終至凶戾。", literal: "Master of Writing He Chang submitted a sealed memorial: \"Formerly when Lady Wu Jiang of Zheng favored Shu Duan and Duke Zhuang of Wei favored Zhou Xu, loving without teaching, in the end they came to violence and perversity.", idiomatic: "Master of Writing He Chang submitted a sealed memorial, saying, \"Formerly when Lady Wu Jiang of Zheng favored Shu Duan and Duke Zhuang of Wei favored Zhou Xu, loving without teaching led in the end to violence and perversity." },
  { zh: "由是觀之，愛子若此，猶饑而食之以毒，適所以害之也。", literal: "Viewed from this, to love a son thus is like feeding him poison when he is hungry—it is precisely what harms him.", idiomatic: "Viewed from this, to love a son thus is like feeding him poison when he is hungry—it is precisely what harms him." },
  { zh: "伏見大將軍憲，始遭大憂，公卿比奏，欲令典干國事。", literal: "Your servant humbly sees Grand General Xian: at first when he met great mourning, the excellencies in succession memorialized wishing to have him preside over state affairs.", idiomatic: "Your servant humbly observes Grand General Xian: at first when he met great mourning, the excellencies in succession memorialized wishing to have him preside over state affairs." },
  { zh: "憲深執謙退，固辭盛位，懇懇勤勤，言之深至，天下聞之，莫不悅喜。", literal: "Xian deeply held to humility and withdrawal, firmly declined the lofty position, earnestly and diligently with words reaching deep within—all under heaven heard it and none did not rejoice.", idiomatic: "Xian deeply held to humility, firmly declined the lofty position, and spoke earnestly and to the depths—all under heaven heard it and rejoiced." },
  { zh: "今逾年未幾，大禮未終，卒然中改，兄弟專朝，憲秉三軍之重，篤、景總宮衛之權，而虐用百姓，奢侈僭逼，誅戳無罪，肆心自快。", literal: "Now not a full year has passed, the great rites are not finished, yet suddenly he changed course midway—the brothers monopolize court; Xian holds the weight of the three armies, Du and Jing together hold palace guard authority, yet they cruelly use the people, are extravagant beyond rank, execute the guiltless, and indulge their hearts for their own pleasure.", idiomatic: "Now scarcely a year has passed and the great mourning rites are not finished, yet suddenly he changed course—the brothers monopolize court; Xian holds command of the three armies, Du and Jing together hold palace guard authority, yet they cruelly abuse the people, live beyond their rank, execute the guiltless, and indulge their own pleasure." },
  { zh: "今者論議哅哅，鹹謂叔段、州吁復生於漢。", literal: "Now discussion clamors and all say Shu Duan and Zhou Xu are reborn in Han.", idiomatic: "Now discussion clamors and all say Shu Duan and Zhou Xu have been reborn in Han." },
  { zh: "臣觀公卿懷持兩端，不肯極言者，以為憲等若有匪懈之志，則已受吉甫褒申伯之功；", literal: "Your servant observes that the excellencies, holding two ends and unwilling to speak to the limit, think that if Xian and the others had a mind not to slacken, they would already have received Jifu praising Lord Shen's merit;", idiomatic: "Your servant observes that the excellencies, straddling both sides and unwilling to speak plainly, think that if Xian and the others should prove diligent they will already have received praise like Jifu praising Lord Shen;" },
  { zh: "如憲等陷於罪辜，則自取陳平、周勃順呂後之權，終不以憲等吉凶為憂也！", literal: "if Xian and the others fall into guilt, they will on their own take Chen Ping and Zhou Bo following Empress Lü's power—in the end they will not take Xian and the others' fortune or ruin as their worry!\"", idiomatic: "if Xian and the others fall into guilt, they will on their own act like Chen Ping and Zhou Bo following Empress Lü's power—in the end they will not take Xian and the others' fortune or ruin as their concern!\"" },
  { zh: "臣敞區區誠欲計策兩安，絕其綿綿，塞其涓涓，上不欲令皇太后損文母之號、陛下有誓泉之譏，下使憲等得長保其福祐也。", literal: "Your servant Chang in his petty sincerity truly wishes to plan so both are secure, cut off the trailing threads, stop the trickling streams—above, not wishing the empress dowager to lose the title of Mother Wen or Your Majesty to bear the reproach of swearing at Quanquan; below, enabling Xian and the others to long preserve their blessing and protection.\"", idiomatic: "Your servant Chang in his petty sincerity truly wishes to plan so both sides are secure, cut off growing troubles at the root, and stop them at the source—above, not wishing the empress dowager to lose the title of Mother Wen or Your Majesty to bear the reproach of swearing at Quanquan; below, enabling Xian and the others to long preserve their blessings.\"" },
  { zh: "駙馬都尉瑰，比請退身，願抑家權，可與參謀，聽順其意，誠宗廟至計，竇氏之福！", literal: "Commandant of the Imperial Son-in-Law Gui has repeatedly asked to withdraw himself and wishes to restrain his family's power—he may be consulted in planning; heed his intent. Truly this is the temple's supreme plan and the Dou clan's blessing!\"", idiomatic: "Commandant of the Imperial Son-in-Law Gui has repeatedly asked to withdraw and wishes to restrain his family's power—he may be consulted in planning; heed his intent. Truly this is the supreme plan for the ancestral temple and the Dou clan's blessing!\"" },
  { zh: "」時濟南王康尊貴驕甚，憲乃白出敞為濟南太傅。", literal: "\" At the time Prince Kang of Jinan was very honored and arrogant; Xian thereupon reported to send Chang out as Grand Tutor of Jinan.", idiomatic: "\" At the time Prince Kang of Jinan was greatly honored and arrogant; Xian reported to send Chang out as Grand Tutor of Jinan." },
  { zh: "康有違失，敞輒諫爭，康雖不能從，然素敬重敞，無所嫌牾焉。", literal: "When Kang had faults Chang would admonish and dispute; though Kang could not follow, yet he had always respected Chang and there was no dislike or conflict.", idiomatic: "When Kang had faults Chang would admonish him; though Kang could not follow, he had always respected Chang and there was no friction between them." },
  { zh: "冬，十月，庚子，阜陵質王延薨。", literal: "In winter, the tenth month, on gengzi, Prince Yan the Material of Fuling died.", idiomatic: "In winter, in the tenth month, on gengzi day, Prince Yan the Material of Fuling died." },
  { zh: "是歲，郡國九大水。", literal: "This year nine commanderies and states suffered great floods.", idiomatic: "That year nine commanderies and states suffered great floods." },
  { zh: "春，正月，丁丑，赦天下。", literal: "In spring, the first month, on dingchou, there was an amnesty for all under heaven.", idiomatic: "In spring, in the first month, on dingchou day, there was an amnesty for all under heaven." },
  { zh: "二月，壬午，日有食之。", literal: "In the second month, on renwu, there was an eclipse of the sun.", idiomatic: "In the second month, on renwu day, there was a solar eclipse." },
  { zh: "夏，五月，丙辰，封皇弟壽為濟北王，開為河間王，淑為城陽王；", literal: "In summer, the fifth month, on bingchen, the emperor's younger brothers Shou were enfeoffed as Prince of Jibei, Kai as Prince of Hejian, and Shu as Prince of Chengyang;", idiomatic: "In summer, in the fifth month, on bingchen day, the emperor's younger brothers Shou, Kai, and Shu were enfeoffed as Princes of Jibei, Hejian, and Chengyang respectively;" },
  { zh: "紹封故淮南頃王子側為常山王。", literal: "continuing the enfeoffment, the former Prince of Huainan Qing's son Ce was enfeoffed as Prince of Changshan.", idiomatic: "and the former Prince of Huainan Qing's son Ce was enfeoffed as Prince of Changshan." },
  { zh: "竇憲遣副校尉閻盤將二千餘騎掩擊北匈奴之守伊吾者，復取其地。", literal: "Dou Xian sent Vice Colonel Yan Pan with more than two thousand horsemen in a surprise attack on the Northern Xiongnu garrison at Yiyi and recovered that territory.", idiomatic: "Dou Xian sent Vice Colonel Yan Pan with more than two thousand horsemen to surprise the Northern Xiongnu garrison at Yiyi and recover the territory." },
  { zh: "車師震懾，前、後王各遣子入侍。", literal: "The Cheshi kings were shaken in awe; the Former and Latter kings each sent sons to attend at court.", idiomatic: "The Cheshi kings were shaken with fear; the Former and Latter kings each sent sons to attend at court." },
  { zh: "月氏求尚公主，班超拒還其使，由是怨恨，遣其副王謝將兵七萬攻超。", literal: "The Yuezhi sought to marry a princess; Ban Chao refused and sent back their envoy; thereby resentful, they sent their vice king Xie leading seventy thousand troops to attack Chao.", idiomatic: "The Yuezhi sought a princess in marriage; Ban Chao refused and sent back their envoy; resentful, they sent their vice king Xie with seventy thousand troops to attack Chao." },
  { zh: "超眾少，皆大恐；", literal: "Chao's forces were few and all were greatly afraid;", idiomatic: "Chao's forces were few and all were greatly afraid;" },
  { zh: "超譬軍士曰：「月氏兵雖多，然數千里逾蔥嶺來，非有運輸，何足憂邪！", literal: "Chao exhorted the soldiers: \"Though Yuezhi troops are many, they have come thousands of li over the Onion Mountains without transport—what is there to worry about!", idiomatic: "Chao exhorted the soldiers, \"Though Yuezhi troops are many, they have come thousands of li over the Onion Mountains without supply trains—what is there to worry about!" },
  { zh: "但當收谷堅守，彼饑窮自降，不過數十日決矣！", literal: "We need only gather grain and hold firm in defense—they will hunger and be exhausted and surrender on their own; the matter will be settled in no more than several tens of days!\"", idiomatic: "We need only gather grain and hold firm—they will hunger and surrender on their own; the matter will be settled in no more than ten days!\"" },
  { zh: "」謝遂前攻超，不下，又鈔掠無所得。", literal: "\" Xie thereupon advanced to attack Chao but could not take him, and again raided and plundered without gain.", idiomatic: "\" Xie advanced to attack Chao but could not take him, and raided without gain." },
  { zh: "超度其糧將盡，必從龜茲求食，乃遣兵數百於東界要之。", literal: "Chao estimated their grain was nearly exhausted and they would surely seek food from Kucha; he therefore sent several hundred troops to the eastern border to intercept them.", idiomatic: "Chao estimated their grain was nearly gone and they would surely seek food from Kucha; he sent several hundred troops to the eastern border to intercept them." },
  { zh: "謝果遣騎繼金銀珠玉以賂龜茲，超伏兵遮擊，盡殺之，持其使首以示謝。", literal: "Xie indeed sent horsemen carrying gold, silver, pearls, and jade to bribe Kucha; Chao's ambush troops intercepted and killed them all, took the envoy's head, and showed it to Xie.", idiomatic: "Xie indeed sent horsemen with gold, silver, pearls, and jade to bribe Kucha; Chao's ambush troops intercepted and killed them all, took the envoy's head, and showed it to Xie." },
  { zh: "謝大驚，即遣使請罪，願得生歸，超縱遣之。", literal: "Xie was greatly alarmed, at once sent an envoy to beg pardon, wished to return alive, and Chao released and sent him away.", idiomatic: "Xie was greatly alarmed, at once sent an envoy to beg pardon and asked to return alive; Chao released him." },
  { zh: "月氏由是大震，歲奉貢獻。", literal: "The Yuezhi thereby were greatly shaken and each year presented tribute.", idiomatic: "The Yuezhi were thereby greatly shaken and each year presented tribute." },
  { zh: "初，北海哀王無後，肅宗以齊武王首創大業而後嗣廢絕，心常愍之，遺詔令復齊、北海二國。", literal: "Earlier Prince Ai of Beihai had no heir; Emperor Suzong, because King Wu of Qi first founded the great enterprise yet his line was cut off, constantly pitied this and in his testamentary edict ordered the restoration of the states of Qi and Beihai.", idiomatic: "Earlier Prince Ai of Beihai had no heir; Emperor Suzong, because King Wu of Qi first founded the great enterprise yet his line was cut off, constantly pitied this and in his testamentary edict ordered the restoration of Qi and Beihai." },
  { zh: "丁卯，封蕪湖侯無忌為齊王，北海敬王庶子威為北海王。", literal: "On dingmao, Marquis Wuji of Wuhu was enfeoffed as Prince of Qi and the Honored King's secondary son Wei of Beihai as Prince of Beihai.", idiomatic: "On dingmao day, Marquis Wuji of Wuhu was enfeoffed as Prince of Qi and the Honored King's secondary son Wei as Prince of Beihai." },
  { zh: "六月，辛卯，中山簡王焉薨。", literal: "In the sixth month, on xinmao, Prince Yan the Plain of Zhongshan died.", idiomatic: "In the sixth month, on xinmao day, Prince Yan the Plain of Zhongshan died." },
  { zh: "焉，東海恭王之母弟，而竇太后，恭王之甥也；", literal: "Yan was the younger brother by the same mother of Prince Gong of Donghai, and Empress Dowager Dou was Prince Gong's sister's child;", idiomatic: "Yan was the younger brother by the same mother of Prince Gong of Donghai, and Empress Dowager Dou was Prince Gong's sister's child;" },
  { zh: "故加賻錢一億，大為修塚塋，平夷吏民塚墓以千數，作者萬餘人，凡征發搖動六州十八郡。", literal: "therefore funeral gifts of money were increased by a hundred million, the tomb and burial ground were greatly repaired, officials' and people's tombs were leveled by the thousands, workers numbered more than ten thousand—in all corvée mobilization shook six provinces and eighteen commanderies.", idiomatic: "therefore funeral gifts were increased by a hundred million cash, the tomb was greatly repaired, officials' and people's graves were leveled by the thousands, workers numbered more than ten thousand—in all corvée mobilization shook six provinces and eighteen commanderies." },
  { zh: "詔封竇憲為冠軍侯，篤為郾侯，瑰為夏陽侯；", literal: "An edict enfeoffed Dou Xian as Marquis of Champion, Du as Marquis of Yan, and Gui as Marquis of Xiayang;", idiomatic: "An edict enfeoffed Dou Xian as Marquis of Champion, Du as Marquis of Yan, and Gui as Marquis of Xiayang;" },
  { zh: "憲獨不受封。", literal: "Xian alone did not accept enfeoffment.", idiomatic: "Xian alone refused the title." },
  { zh: "秋，十月，乙卯，竇憲出屯涼州，以侍中鄧疊行征西將軍事為副。", literal: "In autumn, the tenth month, on yimao, Dou Xian went out to encamp at Liangzhou, with Attendant Within Deng Die acting as Western Expedition General in the deputy role.", idiomatic: "In autumn, in the tenth month, on yimao day, Dou Xian encamped at Liangzhou, with Attendant Within Deng Die acting as Western Expedition General as his deputy." },
  { zh: "北單于以漢還其侍弟，九月，復遣使款塞稱臣，欲入朝見。", literal: "Because the Han returned his attending younger brother, in the ninth month the Northern Shanyu again sent envoys to present themselves at the frontier passes declaring themselves subjects, wishing to enter court for an audience.", idiomatic: "Because the Han had returned his attending younger brother, in the ninth month the Northern Shanyu again sent envoys to the passes declaring submission and wishing to attend court." },
  { zh: "冬十月，竇憲遣班固、梁諷迎之。", literal: "In the tenth month of winter Dou Xian sent Ban Gu and Liang Feng to welcome him.", idiomatic: "In the tenth month of winter Dou Xian sent Ban Gu and Liang Feng to welcome him." },
  { zh: "會南單于復上書求滅北庭，於是遣左谷蠡王師子等將左右部八千騎出雞鹿塞，中郎將耿譚遣從事將護之，襲擊北單于。", literal: "It happened that the Southern Shanyu again memorialized asking to destroy the Northern court; thereupon the Left Guli King Shizi and others were sent leading eight thousand horsemen of the left and right wings out through Jilu Pass, Gentlemen of the Palace Geng Tan sending an Attending Clerk to lead and protect them in a surprise attack on the Northern Shanyu.", idiomatic: "The Southern Shanyu again memorialized asking to destroy the Northern court; thereupon the Left Guli King Shizi was sent with eight thousand horsemen of the left and right wings out through Jilu Pass, and Gentlemen of the Palace Geng Tan sent an Attending Clerk to lead them in a surprise attack on the Northern Shanyu." },
  { zh: "夜至，圍之，北單于被創，僅而得免，獲閼氏及男女五人，斬首八千級，生虜數千口。", literal: "Arriving by night they surrounded him; the Northern Shanyu was wounded and barely escaped; they captured the Yanzhi and five men and women, beheaded eight thousand, and took several thousand living captives.", idiomatic: "Arriving by night they surrounded him; the Northern Shanyu was wounded and barely escaped; they captured the chanyu's consort and five men and women, beheaded eight thousand, and took several thousand captives." },
  { zh: "班固至私渠海而還。", literal: "Ban Gu reached the Private Canal Sea and returned.", idiomatic: "Ban Gu reached the Private Canal Sea and returned." },
  { zh: "是時，南部黨眾益盛，鄰戶三萬四千，勝兵五萬。", literal: "At this time the Southern faction's masses grew ever more flourishing: neighboring households thirty-four thousand, effective troops fifty thousand.", idiomatic: "At this time the Southern Xiongnu grew ever stronger: neighboring households thirty-four thousand, effective troops fifty thousand." },
  { zh: "春，正月，甲子，帝用曹褒新禮，加元服；", literal: "In spring, the first month, on jiazi, the emperor used Cao Bao's new rites and added the cap of manhood;", idiomatic: "In spring, in the first month, on jiazi day, the emperor performed the capping ceremony using Cao Bao's new rites;" },
  { zh: "擢褒監羽林左騎。", literal: "Bao was promoted to oversee the Left Wing of the Forest of Feathers.", idiomatic: "Bao was promoted to oversee the Left Forest Horsemen." },
  { zh: "竇憲以北匈奴微弱，欲遂滅之，二月，遣左校尉耿夔、司馬任尚出居延塞，圍北單于於金微山，大破之，獲其母閼氏、名王以下五千餘級，北單于逃走，不知所在，出塞五千餘里而還，自漢出師所未嘗至也。", literal: "Dou Xian, because the Northern Xiongnu were weak, wished to destroy them utterly; in the second month he sent Left Colonel Geng Kui and Major Ren Shang out through Juyan Pass, surrounded the Northern Shanyu at Mount Jinwei, routed him greatly, captured his mother the Yanzhi and more than five thousand down to titled kings; the Northern Shanyu fled and his whereabouts were unknown; they went beyond the passes more than five thousand li and returned—a place Han armies had never reached since dispatching troops.", idiomatic: "Dou Xian, seeing the Northern Xiongnu weakened, wished to destroy them utterly; in the second month he sent Left Colonel Geng Kui and Major Ren Shang out through Juyan Pass, surrounded the Northern Shanyu at Mount Jinwei, routed him utterly, captured his mother the chanyu's consort and more than five thousand down to titled kings; the Northern Shanyu fled and his whereabouts were unknown; they went more than five thousand li beyond the passes and returned—to a place Han armies had never reached." },
  { zh: "封夔為粟邑侯。", literal: "Kui was enfeoffed as Marquis of Suyi.", idiomatic: "Kui was enfeoffed as Marquis of Suyi." },
  { zh: "竇憲既立大功，威名益盛，以耿夔、任尚等為爪牙，鄧疊、郭璜為心腹，班固、傅毅之徒典文章，刺史、守、令，多出其門，競賦斂吏民，共為賂遺。", literal: "Dou Xian having established great merit, his prestige and name grew ever greater; he took Geng Kui, Ren Shang, and others as claws and teeth, Deng Die and Guo Huang as heart and belly, Ban Gu, Fu Yi, and such as masters of literary composition; many provincial inspectors, administrators, and magistrates came from his gate, vying to levy exactions on officials and people and together making bribes and gifts.", idiomatic: "Dou Xian having established great merit, his prestige grew ever greater; he took Geng Kui, Ren Shang, and others as his claws and teeth, Deng Die and Guo Huang as his inner circle, Ban Gu, Fu Yi, and such to handle literary matters; many provincial inspectors, administrators, and magistrates came from his faction, vying to levy exactions on officials and people and together making bribes." },
  { zh: "司徒袁安、司空任隗舉奏諸二千石並所連及，貶秩免官者四十餘人，竇氏大恨；", literal: "Grand Tutor Yuan An and Minister of Works Ren Wei jointly memorialized and impeached various two-thousand-bushel officials and those connected with them; more than forty had rank reduced or office removed—the Dou clan hated this greatly;", idiomatic: "Grand Tutor Yuan An and Minister of Works Ren Wei jointly impeached various two-thousand-bushel officials and those connected with them; more than forty were demoted or dismissed—the Dou clan hated this greatly;" },
  { zh: "但安、隗素行高，亦未有以害之。", literal: "but An and Wei by nature conducted themselves on high ground and there was also no means to harm them.", idiomatic: "but An and Wei were of high character by nature and there was no means to harm them." },
  { zh: "尚書僕射樂恢，刺舉無所迴避，憲等疾之。", literal: "Vice Director of the Masters of Writing Yue Hui impeached and investigated without turning aside; Xian and the others resented him.", idiomatic: "Vice Director of the Masters of Writing Yue Hui investigated and impeached without turning aside; Xian and the others resented him." },
  { zh: "恢上疏曰：「陛下富於春秋，纂承大業，諸舅不宜干正王室，以示天下之私。", literal: "Hui submitted: \"Your Majesty is rich in years of spring and autumn and has inherited the great enterprise; the various maternal uncles ought not interfere in correcting the royal house, lest it show the realm's partiality.", idiomatic: "Hui submitted, \"Your Majesty is young and has inherited the great enterprise; the maternal uncles ought not interfere in the royal house, lest it show partiality to the realm." },
  { zh: "方今之宜，上以義自割，下以謙自引，四舅可長保爵土之榮，皇太后永無慚負宗廟之憂，誠策之上者也。", literal: "What is fitting at present is that above you cut yourself by righteousness and below they withdraw themselves by humility—the four uncles can long preserve the glory of rank and fief, the empress dowager will forever have no shame or burden for the ancestral temple—truly this is the supreme stratagem.\"", idiomatic: "What is fitting now is that above you restrain yourself by righteousness and below they withdraw by humility—the four uncles can long preserve rank and fief, the empress dowager will forever have no shame before the ancestral temple—truly this is the best policy.\"" },
  { zh: "」書奏，不省。", literal: "\" When the memorial was submitted it was not heeded.", idiomatic: "\" When the memorial was submitted it was not heeded." },
  { zh: "恢稱疾乞骸骨，歸長陵；", literal: "Hui claimed illness and begged his old bones, returning to Changling;", idiomatic: "Hui claimed illness and begged to retire, returning to Changling;" },
  { zh: "憲風厲州郡，迫脅恢飲藥死。", literal: "Xian sent stern orders through the provinces and commanderies and coerced Hui to drink poison and die.", idiomatic: "Xian sent stern orders through the provinces and commanderies and coerced Hui to drink poison and die." },
  { zh: "於是朝臣震懾，望風承旨，無敢違者。", literal: "Thereupon court ministers were shaken in awe, caught his wind and followed his intent, and none dared disobey.", idiomatic: "Thereupon court ministers were shaken with fear, caught his intent, and none dared disobey." },
  { zh: "袁安以天子幼弱，外戚擅權，每朝會進見及與公卿言國家事，未嘗不喑嗚流涕；", literal: "Yuan An, because the Son of Heaven was young and weak and the maternal kin monopolized power, whenever at court assembly he advanced to be seen or spoke with the excellencies on state affairs, never failed to sob and weep with choked voice;", idiomatic: "Yuan An, because the emperor was young and weak and the maternal kin monopolized power, whenever he attended court or spoke with the excellencies on state affairs never failed to sob and weep;" },
  { zh: "自天子及大臣，皆恃賴之。", literal: "from the Son of Heaven down to the great ministers, all relied on him.", idiomatic: "from the emperor down to the great ministers, all relied on him." },
  { zh: "冬，十月，癸未，上行幸長安，詔求蕭、曹近親宜為嗣者，紹其封邑。", literal: "In winter, the tenth month, on guiwei, the emperor traveled in person to Chang'an and edicted to seek near kin of Xiao and Cao suitable as heirs and continue their enfeoffed territories.", idiomatic: "In winter, in the tenth month, on guiwei day, the emperor traveled to Chang'an and edicted to seek near kin of the Xiao and Cao families suitable as heirs and continue their fiefs." },
  { zh: "詔竇憲與車駕會長安。", literal: "An edict ordered Dou Xian to meet the imperial carriage at Chang'an.", idiomatic: "An edict ordered Dou Xian to meet the imperial carriage at Chang'an." },
  { zh: "憲至，尚書以下議欲拜之，伏稱萬歲，尚書韓稜正色曰：「夫上交不諂，下交不黷；", literal: "When Xian arrived, those from the Masters of Writing down discussed wishing to bow to him and prostrate themselves calling \"ten thousand years\"; Master of Writing Han Ling with stern countenance said: \"Superiors in interaction do not flatter; inferiors in interaction do not be disrespectful;", idiomatic: "When Xian arrived, those from the Masters of Writing down discussed bowing to him and prostrating themselves calling \"ten thousand years\"; Master of Writing Han Ling said sternly, \"Superiors in interaction do not flatter; inferiors in interaction do not be disrespectful;" },
  { zh: "禮無人臣稱萬歲之制！", literal: "in rites there is no regulation for subjects to call 'ten thousand years'!\"", idiomatic: "in rites there is no regulation for subjects to call 'ten thousand years'!\"" },
  { zh: "」議者皆慚而止。", literal: "\" The discussants all were ashamed and stopped.", idiomatic: "\" The discussants were all ashamed and stopped." },
  { zh: "尚書左丞王龍私奏記、上牛酒於憲，稜舉奏龍，論為城旦。", literal: "Left Assistant Master of Writing Wang Long privately submitted a note and presented oxen and wine to Xian; Ling impeached Long and he was sentenced to corvée labor at dawn.", idiomatic: "Left Assistant Master of Writing Wang Long privately submitted a note and presented oxen and wine to Xian; Ling impeached Long and he was sentenced to corvée labor." },
  { zh: "龜茲、姑墨、溫宿諸國皆降。", literal: "Kucha, Gumo, Wensu, and the various states all surrendered.", idiomatic: "Kucha, Gumo, Wensu, and the various states all surrendered." },
  { zh: "十二月，復置西域都護、騎都尉、戊己校尉官。", literal: "In the twelfth month the offices of Protector-General of the Western Regions, Commandant of Cavalry, and Colonel of the Garrison of Wu and Ji were restored.", idiomatic: "In the twelfth month the offices of Protector-General of the Western Regions, Commandant of Cavalry, and Colonel of the Garrison of Wu and Ji were restored." },
  { zh: "以班超為都護，徐幹為長史。", literal: "Ban Chao was made Protector-General and Xu Gan Chief Clerk.", idiomatic: "Ban Chao was made Protector-General and Xu Gan Chief Clerk." },
  { zh: "拜龜茲侍子白霸為龜茲王，遣司馬姚光送之。", literal: "Kucha's attending prince Bai Ba was appointed King of Kucha and Army Major Yao Guang was sent to escort him.", idiomatic: "Kucha's hostage prince Bai Ba was appointed King of Kucha and Army Major Yao Guang was sent to escort him." },
  { zh: "超與光共脅龜茲，廢其王尤利多而立白霸，使光將尤利多還詣京師。", literal: "Chao together with Guang jointly coerced Kucha, deposed its king Youliduo and established Bai Ba, and sent Guang to lead Youliduo back to present himself at the capital.", idiomatic: "Chao and Guang jointly coerced Kucha, deposed King Youliduo and installed Bai Ba, and sent Guang to lead Youliduo back to the capital." },
  { zh: "超居龜茲它乾城，徐幹屯疏勒，惟焉耆、危須、尉犁以前沒都護，猶懷二心，其餘悉定。", literal: "Chao resided at Kucha's Taqian city, Xu Gan encamped at Shule; only Yanqi, Weixu, and Weili, because they had earlier destroyed the Protector-General, still harbored two minds—the rest were all settled.", idiomatic: "Chao resided at Kucha's Taqian city and Xu Gan encamped at Shule; only Yanqi, Weixu, and Weili, because they had earlier killed a Protector-General, still wavered—the rest were all settled." },
  { zh: "庚辰，上至自長安。", literal: "On gengchen the emperor returned from Chang'an.", idiomatic: "On gengchen day the emperor returned from Chang'an." },
  { zh: "初，北單于既亡，其弟右谷蠡王於除鞬自立為單于，將眾數千人止蒲類海，遣使款塞。", literal: "Earlier, once the Northern Shanyu was destroyed, his younger brother the Right Guli King Yuchujian declared himself Shanyu, led several thousand of the masses and halted at Lake Pulei, and sent envoys to present themselves at the passes.", idiomatic: "Earlier, once the Northern Shanyu was destroyed, his younger brother the Right Guli King Yuchujian declared himself Shanyu, led several thousand followers and halted at Lake Pulei, and sent envoys to the passes." },
  { zh: "竇憲請遣使立於除鞬為單于，置中郎將領護，如南單于故事。", literal: "Dou Xian requested sending envoys to establish Yuchujian as Shanyu, setting Gentlemen of the Palace to lead and protect him according to the Southern Shanyu precedent.", idiomatic: "Dou Xian requested sending envoys to establish Yuchujian as Shanyu and posting Gentlemen of the Palace to lead and protect him according to the Southern Shanyu precedent." },
  { zh: "事下公卿議，宋由等以為可許；", literal: "The matter was sent down to the excellencies for discussion; Song You and others thought it could be permitted;", idiomatic: "The matter was sent to the excellencies for discussion; Song You and others thought it could be approved;" },
  { zh: "袁安、任隗奏以為：「光武招懷南虜，非謂可永安內地，正以權時之算，可得扞御北狄故也。", literal: "Yuan An and Ren Wei memorialized, holding: \"Emperor Guangwu's winning over of the southern barbarians was not to say the inner lands could be forever secure—it was precisely because of timely expedient calculation that they could be obtained to defend against the northern Di.\"", idiomatic: "Yuan An and Ren Wei memorialized, saying, \"Emperor Guangwu's winning over of the southern barbarians was not because the inner lands could be forever secure—it was precisely a timely expedient by which they could be obtained to defend against the northern barbarians.\"" },
  { zh: "今朔漠既定，宜令南單于反其北庭，並領降眾，無緣復更立於除鞬以增國費。", literal: "Now the northern desert is settled; it is fitting to order the Southern Chanyu to return to his northern court and jointly lead the surrendered masses—there is no occasion to again establish Yu Chujian and increase state expense.", idiomatic: "Now that the northern desert is settled, the Southern Chanyu should be ordered to return to his northern court and take charge of all surrendered peoples as well; there is no reason to establish Yu Chujian anew and increase state expense." },
  { zh: "」事奏，未以時定。", literal: "\" When the memorial was submitted, it was not decided in time.", idiomatic: "When the memorial was submitted, it was not decided in time." },
  { zh: "安懼憲計遂行，乃獨上封事曰：「南單于屯先父舉眾歸德，自蒙恩以來四十餘年，三帝積累以遺陛下，陛下深宜遵述先志，成就其業，況屯首唱大謀，空盡北虜，輟而弗圖，更立新降；", literal: "An feared Xian's plan would be carried out and thereupon alone submitted a sealed memorial, saying: \"The Southern Chanyu Tun—his father formerly led the masses to submit in virtue; since receiving grace more than forty years have passed; three emperors accumulated and bequeathed to Your Majesty; Your Majesty should deeply follow and trace the former intent and complete his enterprise; moreover Tun was first to propose the great plan and utterly exhausted the northern barbarians—then to stop and not pursue it while instead establishing the newly surrendered;", idiomatic: "An feared Xian's plan would be carried out and thereupon submitted a sealed memorial alone, saying, \"The Southern Chanyu Tun—his father formerly led the masses to submit in allegiance; since receiving grace more than forty years have passed, and three emperors accumulated and bequeathed to Your Majesty—Your Majesty should deeply follow the former intent and complete his enterprise. Moreover Tun was first to propose the great plan and utterly exhausted the northern barbarians—then to stop and not pursue it while instead establishing the newly surrendered;" },
  { zh: "以一朝之計，違三世之規，失信於所養，建立於無功。", literal: "by a single court's scheme to violate three generations' rule, break faith with those fostered, and establish on those without merit.", idiomatic: "by a single court's scheme to violate three generations' policy, break faith with those you have fostered, and establish reward on those without merit." },
  { zh: "《論語》曰：『言忠信，行篤敬，雖蠻貊行焉。", literal: "The Analects says: \"Speak with loyalty and faith, act with earnest respect—even among barbarians one may go.", idiomatic: "The Analects says, \"Speak with loyalty and faith, act with earnest respect—even among barbarians one may go.\"" },
  { zh: "』今若失信於一屯，則百蠻不敢復保誓矣。", literal: "\" Now if faith is broken with this one Tun, then the hundred barbarians will not dare again to keep their oaths.", idiomatic: "Now if faith is broken with this one Tun, then the hundred barbarians will not dare again to keep their oaths." },
  { zh: "又，烏桓、鮮卑新殺北單于，凡人之情，鹹畏仇讎，今立其弟，則二虜懷怨。", literal: "Moreover, the Wuhuan and Xianbei have newly killed the Northern Chanyu; the common disposition of men—all fear their foes and enemies; now to establish his younger brother will make the two barbarians harbor resentment.", idiomatic: "Moreover, the Wuhuan and Xianbei have newly killed the Northern Chanyu; it is human nature that all fear their foes and enemies—now to establish his younger brother will make the two barbarians harbor resentment." },
  { zh: "且漢故事，供給南單于，費直歲一億九十餘萬，西域歲七千四百八十萬；", literal: "Moreover, Han precedent supplies the Southern Chanyu at a cost of more than one hundred nine million per year; the Western Regions seven thousand four hundred eighty thousand per year;", idiomatic: "Moreover, by Han precedent the supply for the Southern Chanyu costs more than one hundred nine million cash per year, and for the Western Regions seven thousand four hundred eighty thousand per year;" },
  { zh: "今北庭彌遠，其費過倍，是乃空盡天下而非建策之要地。", literal: "now the northern court is ever farther—its expense more than doubled; this is to empty all under Heaven, not the essential point of founding policy.", idiomatic: "now the northern court is ever farther and the expense more than doubled—this would empty all under Heaven, not the essential point of founding policy.\"" },
  { zh: "」詔下其議，安又與憲更相難折。", literal: "\" An edict sent down their deliberation; An again with Xian repeatedly rebutted and debated.", idiomatic: "An edict sent down their deliberation; An again debated sharply back and forth with Xian." },
  { zh: "憲險急負執，言辭驕訐，至詆毀安，稱光武誅韓歆、戴涉故事，安終不移；", literal: "Xian was dangerous, hasty, and stubbornly obstinate; his words proud and deceitful, even to slandering An and citing Guangwu's execution of Han Xin and Dai She as precedent—An in the end did not shift;", idiomatic: "Xian was dangerous, hasty, and stubbornly obstinate; his words were proud and deceitful, even to slandering An and citing Guangwu's execution of Han Xin and Dai She as precedent—An in the end did not yield;" },
  { zh: "然上竟從憲策。", literal: "yet the Emperor in the end followed Xian's plan.", idiomatic: "yet the Emperor in the end followed Xian's plan." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
